-- Researched and checked against official sites in Oct 2026 (source_url records where).
-- Generated by scripts/import-listings.js; edit freely.
INSERT INTO listings
  (category_id, slug, name, kind, description, address, neighborhood, lat, lng, transit, phone, website, cost, tags, is_free, source_url)
SELECT c.id, v.slug, v.name, v.kind, v.description, v.address, v.neighborhood, v.lat, v.lng,
       v.transit, v.phone, v.website, v.cost, v.tags, v.is_free, v.source_url
FROM (VALUES
  ('doctors', 'planned-parenthood-brooklyn', 'Planned Parenthood – Joan Malin Brooklyn Health Center', 'Sexual & reproductive health', 'Planned Parenthood''s Brooklyn center by Borough Hall offers birth control, STI testing, abortion, gynecologic care, vaccines and gender-affirming care. You can walk in during open hours to book or check for a same-day appointment.', '44 Court St, 4th Floor, Brooklyn, NY 11201', 'Downtown Brooklyn', 40.6929::float8, -73.9907::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, walk 6 min.', '212-965-7000', 'https://www.plannedparenthood.org/health-center/new-york/brooklyn/11201/joan-malin-brooklyn-health-center-2522-91110', 'Insurance, Medicaid and sliding-scale fees', ARRAY['sliding-scale','medicaid','women-focused','lgbtq-affirming','walk-in','confidential','evening-hours']::text[], false, 'https://www.plannedparenthood.org/health-center/new-york/brooklyn/11201/joan-malin-brooklyn-health-center-2522-91110'),
  ('doctors', 'nyc-sexual-health-clinic-fort-greene', 'NYC Sexual Health Clinic – Fort Greene (incl. Express Clinic)', 'Sexual & reproductive health', 'A city Health Department clinic offering STI and HIV testing and treatment, PrEP/PEP and emergency contraception, with a first-floor Express Clinic for quick testing. Sliding-scale fees, and you won''t be turned away if you can''t pay.', '295 Flatbush Ave Ext, Brooklyn, NY 11201', 'Downtown Brooklyn / Fort Greene', 40.6907::float8, -73.9824::float8, 'B from Grand St to DeKalb Av (weekdays), walk 3 min; or F to Jay St–MetroTech, walk 8 min.', '347-396-7959', 'https://www.nyc.gov/site/doh/services/sexual-health-clinics.page', 'Sliding scale; no proof of income; services even if you can''t pay', ARRAY['low-cost','sliding-scale','no-insurance-ok','confidential','walk-in']::text[], false, 'https://www.nyc.gov/site/doh/services/sexual-health-clinics.page'),
  ('doctors', 'callen-lorde-brooklyn', 'Callen-Lorde Brooklyn', 'Primary care', 'Callen-Lorde''s Brooklyn health center offers LGBTQ+-affirming primary care, sexual health, women''s health, transgender health and behavioral health. Care is provided regardless of ability to pay.', '40 Flatbush Ave Ext, 3rd Floor, Brooklyn, NY 11201', 'Downtown Brooklyn', 40.6955::float8, -73.9838::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, walk 6 min.', '718-215-1818', 'https://callen-lorde.org/brooklyn/', 'Medicaid, Medicare and commercial plans; sliding scale ($0–$100 visits) if uninsured', ARRAY['sliding-scale','medicaid','no-insurance-ok','lgbtq-affirming','evening-hours']::text[], false, 'https://callen-lorde.org/brooklyn/'),
  ('doctors', 'chn-lower-east-side', 'Community Healthcare Network – Lower East Side', 'Primary care', 'A nonprofit federally qualified health center a short walk from the LES offering primary care for the whole family, with Spanish-speaking staff. CHN says it never turns anyone away.', '255 E Houston St, New York, NY 10002', 'Lower East Side', 40.7215::float8, -73.9866::float8, 'Walk 10 min, or F from Delancey St–Essex St to 2 Av, walk 3 min.', '212-477-1120', 'https://www.chnnyc.org/locations/', 'Most insurance and Medicaid; uninsured patients not turned away', ARRAY['medicaid','no-insurance-ok','spanish','evening-hours']::text[], false, 'https://www.chnnyc.org/locations/'),
  ('doctors', 'chn-williamsburg', 'Community Healthcare Network – Williamsburg', 'Primary care', 'A nonprofit community health center in East Williamsburg offering family primary care. CHN says it never turns anyone away. Also offers dental and eye care on site.', '94-98 Manhattan Ave, Brooklyn, NY 11206', 'Williamsburg', 40.7034::float8, -73.9443::float8, 'J/M from Delancey St–Essex St to Flushing Av, walk 10 min.', '718-388-0390', 'https://www.chnnyc.org/locations/', 'Most insurance and Medicaid; uninsured patients not turned away', ARRAY['medicaid','no-insurance-ok']::text[], false, 'https://www.chnnyc.org/locations/'),
  ('doctors', 'chn-long-island-city', 'Community Healthcare Network – Long Island City', 'Primary care', 'A nonprofit community health center in Long Island City offering family primary care. CHN says it never turns anyone away. Also offers dental and eye care on site.', '36-11 21st St, Long Island City, NY 11106', 'Long Island City', 40.759::float8, -73.9375::float8, 'F from Delancey St–Essex St to 21 St–Queensbridge, walk 10 min.', '718-482-7772', 'https://www.chnnyc.org/locations/', 'Most insurance and Medicaid; uninsured patients not turned away', ARRAY['medicaid','no-insurance-ok']::text[], false, 'https://www.chnnyc.org/locations/'),
  ('doctors', 'ryan-health-chelsea-clinton', 'Ryan Health – Chelsea-Clinton', 'Primary care', 'A Ryan Health community health center in Hell''s Kitchen with primary care, women''s health, and sexual and reproductive health, plus dental and behavioral health. Ryan Health offers a sliding-fee discount for patients who qualify based on income. Also offers dental and eye care on site.', '645 10th Ave, New York, NY 10036', 'Hell''s Kitchen', 40.7617::float8, -73.993::float8, 'F from Delancey St–Essex St to W 4 St, transfer to C/E to 50 St, walk 5 min.', '212-749-1820', 'https://ryanhealth.org/locations/ryan-chelsea-clinton-community-health-center', 'Insurance and Medicaid; sliding-fee discount for eligible uninsured patients', ARRAY['sliding-scale','medicaid','no-insurance-ok','evening-hours']::text[], false, 'https://ryanhealth.org/locations/ryan-chelsea-clinton-community-health-center'),
  ('doctors', 'ryan-health-west-97th', 'Ryan Health – West 97th Street', 'Primary care', 'Ryan Health''s Upper West Side flagship offers primary care, sexual and reproductive health, HIV prevention and care, dental and eye care. A sliding-fee discount is available for patients who qualify based on income. Also offers dental and eye care on site.', '110 W 97th St, New York, NY 10025', 'Upper West Side', 40.7942::float8, -73.9673::float8, 'B from Grand St to 96 St (weekdays), walk 3 min.', '212-749-1820', 'https://ryanhealth.org/locations/william-f-ryan-community-health-center', 'Insurance and Medicaid; sliding-fee discount for eligible uninsured patients', ARRAY['sliding-scale','medicaid','no-insurance-ok','evening-hours']::text[], false, 'https://ryanhealth.org/locations/william-f-ryan-community-health-center'),
  ('doctors', 'ryan-health-women-and-childrens', 'Ryan Health – Women & Children''s', 'Sexual & reproductive health', 'A Ryan Health center focused on women''s and children''s care, offering OB/GYN, primary care, and sexual and reproductive health, plus WIC services for those eligible. A sliding-fee discount is available for patients who qualify based on income.', '801 Amsterdam Ave, New York, NY 10025', 'Upper West Side', 40.7966::float8, -73.9695::float8, 'B from Grand St to 96 St (weekdays), walk 6 min.', '212-749-1820', 'https://ryanhealth.org/locations/ryan-women-and-childrens', 'Insurance and Medicaid; sliding-fee discount for eligible uninsured patients', ARRAY['sliding-scale','medicaid','no-insurance-ok','women-focused']::text[], false, 'https://ryanhealth.org/locations/ryan-women-and-childrens'),
  ('doctors', 'institute-for-family-health-17th-street', 'The Institute for Family Health at 17th Street', 'Primary care', 'A nonprofit community health center in Chelsea offering primary care, behavioral health, HIV services, and help enrolling in insurance and benefits. It is accepting new patients.', '230 W 17th St, New York, NY 10011', 'Chelsea', 40.7413::float8, -73.9989::float8, 'F/M from Delancey St–Essex St to 14 St, walk 7 min.', '212-206-5200', 'https://institute.org/locations/', 'Insurance accepted; on-site help with insurance enrollment', '{}'::text[], false, 'https://institute.org/locations/'),
  ('doctors', 'nyc-health-hospitals-gotham-cumberland', 'NYC Health + Hospitals/Gotham Health, Cumberland', 'Primary care', 'A public community health center in Fort Greene with adult primary care, behavioral health, dental and dermatology, open evenings and Saturdays. Uninsured New Yorkers can get low- or no-cost care through NYC Care regardless of immigration status.', '100 N Portland Ave, Brooklyn, NY 11205', 'Fort Greene', 40.696::float8, -73.9768::float8, 'B from Grand St to DeKalb Av (weekdays), walk 12 min.', '844-692-4692', 'https://www.nychealthandhospitals.org/locations/gotham-health-cumberland/', 'Insurance and Medicaid; NYC Care low/no-cost option for uninsured', ARRAY['low-cost','medicaid','no-insurance-ok','evening-hours']::text[], false, 'https://www.nychealthandhospitals.org/locations/gotham-health-cumberland/'),
  ('doctors', 'nyc-health-hospitals-woodhull', 'NYC Health + Hospitals/Woodhull', 'Urgent & emergency', 'A public hospital on the Bushwick–Williamsburg border with a 24/7 emergency department, primary care, and a women''s health service providing OB/GYN and midwifery care. Uninsured patients can use NYC Care regardless of immigration status.', '760 Broadway, Brooklyn, NY 11206', 'Bushwick / Williamsburg', 40.6997::float8, -73.9426::float8, 'J/M from Delancey St–Essex St to Flushing Av, walk 2 min.', '718-963-8000', 'https://www.nychealthandhospitals.org/locations/woodhull/', 'Insurance and Medicaid; NYC Care low/no-cost option for uninsured', ARRAY['24-7','medicaid','no-insurance-ok','low-cost']::text[], false, 'https://www.nychealthandhospitals.org/woodhull/contact/'),
  ('doctors', 'nyc-health-hospitals-metropolitan', 'NYC Health + Hospitals/Metropolitan', 'Urgent & emergency', 'A full-service public hospital in East Harlem with an emergency department, between 97th and 99th Streets on First Avenue. Uninsured patients can use NYC Care regardless of immigration status.', '1901 First Ave, New York, NY 10029', 'East Harlem', 40.7848::float8, -73.9447::float8, '6 from Spring St to 96 St, walk 8 min.', '212-423-6262', 'https://www.nychealthandhospitals.org/metropolitan/', 'Insurance and Medicaid; NYC Care low/no-cost option for uninsured', ARRAY['24-7','medicaid','no-insurance-ok','low-cost']::text[], false, 'https://www.nychealthandhospitals.org/metropolitan/'),
  ('doctors', 'columbia-health-medical-services', 'Columbia Health – Medical Services', 'Student health', 'Columbia''s student health clinic in John Jay Hall offers primary, same-day and sexual & reproductive health care, with Saturday hours during the term. For eligible Columbia students; students can call for after-hours urgent advice.', 'John Jay Hall, 4th Floor, 519 W 114th St, New York, NY 10027', 'Morningside Heights', 40.8061::float8, -73.9625::float8, 'D from Grand St to 59 St–Columbus Circle, transfer to 1 to 116 St–Columbia University, walk 3 min.', '212-854-7426', 'https://www.health.columbia.edu/content/hours-and-locations', 'For eligible Columbia students', ARRAY['student-friendly','confidential']::text[], false, 'https://www.health.columbia.edu/content/hours-and-locations'),
  ('doctors', 'barnard-primary-care-health-service', 'Barnard Primary Care Health Service', 'Student health', 'Barnard''s on-campus clinic offers primary and gynecologic care, STI screening and pregnancy options counseling, with after-hours triage by phone. For Barnard students only; no walk-ins.', 'Brooks Hall, Lower Level, 3009 Broadway, New York, NY 10027', 'Morningside Heights', 40.8095::float8, -73.9636::float8, 'D from Grand St to 59 St–Columbus Circle, transfer to 1 to 116 St–Columbia University, walk 2 min.', '212-854-2091', 'https://barnard.edu/health-wellness/student-health', 'For Barnard students', ARRAY['student-friendly','women-focused','confidential']::text[], false, 'https://barnard.edu/health-wellness/student-health'),
  ('doctors', 'fit-health-services', 'FIT Health Services', 'Student health', 'The Fashion Institute of Technology''s on-campus health office in the Dubinsky Student Center, with evening and Saturday hours for evening/weekend students. For FIT students.', 'Room A402, David Dubinsky Student Center, 227 W 27th St, New York, NY 10001', 'Chelsea', 40.747::float8, -73.9935::float8, 'F/M from Delancey St–Essex St to 23 St, walk 8 min.', '212-217-4190', 'https://www.fitnyc.edu/life-at-fit/health-and-wellness/health-services/index.php', 'For FIT students; ask about any fees', ARRAY['student-friendly','evening-hours']::text[], false, 'https://www.fitnyc.edu/health-services/index.php'),
  ('doctors', 'hunter-college-health-services', 'Hunter College Health Services Office', 'Student health', 'Hunter''s campus health office handles immunization records and offers free HIV and STI testing plus referrals to community care. For Hunter students.', 'North Building, Room N307, 695 Park Ave, New York, NY 10065', 'Upper East Side', 40.7685::float8, -73.9647::float8, '6 from Spring St to 68 St–Hunter College, walk 1 min.', '212-772-4800', 'https://www.hunter.cuny.edu/directory/department/9946/', 'Free HIV/STI testing for Hunter students', ARRAY['student-friendly','free','confidential']::text[], true, 'https://www.hunter.cuny.edu/directory/department/9946/'),
  ('doctors', 'baruch-student-health-care-center', 'Baruch College Student Health Care Center', 'Student health', 'Baruch''s on-campus clinic evaluates, diagnoses and treats a broad range of illnesses and injuries. Free for students with a valid Baruch ID.', '138 E 26th St, Main Floor, New York, NY 10010', 'Gramercy / Kips Bay', 40.741::float8, -73.983::float8, '6 from Spring St to 28 St, walk 4 min.', '646-312-2040', 'https://studentaffairs.baruch.cuny.edu/health/', 'Free for students with a valid Baruch ID', ARRAY['student-friendly','free']::text[], true, 'https://studentaffairs.baruch.cuny.edu/health/'),
  ('doctors', 'pace-university-health-care-nyc', 'Pace University Health Care – NYC Campus', 'Student health', 'Pace''s nurse-practitioner-run clinic offers primary care, immunizations, physicals and gynecological services. For Pace students, faculty and staff; appointments only, no walk-ins.', '161 William St, 2nd Floor, Room 212, New York, NY 10038', 'Financial District', 40.7095::float8, -74.0066::float8, 'J/Z from Bowery to Fulton St, walk 3 min.', '212-346-1600', 'https://www.pace.edu/college-health-professions/life-chp/university-health-care', 'For the Pace community; ask about fees', ARRAY['student-friendly']::text[], false, 'https://www.pace.edu/college-health-professions/life-chp/university-health-care'),
  ('doctors', 'new-school-student-health-services', 'The New School Student Health Services', 'Student health', 'The New School''s student health office provides medical and mental health services near Union Square; book through the SHS Portal or by phone. For New School students.', '80 Fifth Ave, 3rd Floor, New York, NY 10011', 'Greenwich Village / Union Square', 40.7357::float8, -73.9939::float8, '6 from Spring St to 14 St–Union Sq, walk 5 min.', '212-229-1671', 'https://www.newschool.edu/health-services/', 'For New School students', ARRAY['student-friendly']::text[], false, 'https://www.newschool.edu/health-services/medical/'),
  ('doctors', 'pratt-health-services', 'Pratt Institute Health Services', 'Student health', 'Pratt''s campus clinic offers basic health care, gynecologic care, STI testing and treatment, and LGBTQ+-specific care, in person or by telehealth. No charge for Pratt students (diagnostic tests may go through insurance).', 'Student Wellness Center, 2nd Floor, 200 Willoughby Ave, Brooklyn, NY 11205', 'Clinton Hill', 40.6914::float8, -73.9632::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, transfer to C to Clinton–Washington Avs, walk 8 min.', '718-399-4542', 'https://www.pratt.edu/administrative-departments/student-affairs/health-wellness/health-services/', 'No charge for Pratt students; lab tests may involve insurance copays', ARRAY['student-friendly','free','lgbtq-affirming','telehealth']::text[], true, 'https://www.pratt.edu/administrative-departments/student-affairs/health-wellness/health-services/'),
  ('doctors', 'bmcc-health-wellness-services', 'BMCC Health & Wellness Services', 'Student health', 'Borough of Manhattan Community College''s health office offers first aid, health counseling and referrals, and free HIV/STI testing. For BMCC students.', '199 Chambers St, Room N-380, New York, NY 10007', 'Tribeca', 40.7179::float8, -74.0118::float8, 'J/Z from Bowery to Chambers St, walk 12 min.', '212-220-8256', 'https://www.bmcc.cuny.edu/student-affairs/health-services/', 'Free HIV/STI testing for BMCC students', ARRAY['student-friendly','free']::text[], true, 'https://www.bmcc.cuny.edu/student-affairs/health-services/'),
  ('doctors', 'laguardia-cc-health-services-center', 'LaGuardia Community College Health Services Center', 'Student health', 'LaGuardia''s campus health center offers HIV, STI and pregnancy screening, PrEP/PEP consultations and health insurance enrollment help, and refers students out for OB/GYN care. For LaGuardia students.', 'M-Building, Room MB-40, 31-10 Thomson Ave, Long Island City, NY 11101', 'Long Island City', 40.7443::float8, -73.935::float8, '6 from Spring St to Grand Central–42 St, transfer to 7 to 33 St–Rawson St, walk 3 min.', '718-482-5280', 'https://www.laguardia.edu/students/health-services-center/', 'For LaGuardia students', ARRAY['student-friendly','lgbtq-affirming']::text[], false, 'https://www.laguardia.edu/students/health-services-center/'),
  ('doctors', 'parkmed-nyc', 'Parkmed NYC', 'Sexual & reproductive health', 'A physician-owned Midtown East clinic offering medication and in-clinic abortion, gynecological care, STI testing and contraception, plus telehealth for abortion pills. Open seven days, with care available regardless of age or immigration status.', '800 2nd Ave, Suite 605, New York, NY 10017', 'Midtown East', 40.75::float8, -73.9714::float8, '6 from Spring St to Grand Central–42 St, walk 6 min.', '212-686-6066', 'https://www.parkmed.com/', 'Medicaid and most insurance; financial assistance available', ARRAY['medicaid','women-focused','telehealth','confidential','evening-hours']::text[], false, 'https://www.parkmed.com/'),
  ('doctors', 'mount-sinai-urgent-care-east-14th', 'Mount Sinai Urgent Care – East 14th Street', 'Urgent & emergency', 'A Mount Sinai walk-in urgent care in the East Village that is open 24 hours a day; no appointment needed. Accepts all insurance plans including Medicaid, with self-pay options for uninsured patients.', '310 E 14th St, Ground Floor, New York, NY 10003', 'East Village', 40.7314::float8, -73.9829::float8, '6 from Spring St to 14 St–Union Sq, transfer to L to 1 Av, walk 2 min.', NULL::text, 'https://www.mountsinai.org/locations/urgent-care-east-14th-street', 'All insurance incl. Medicaid; self-pay available', ARRAY['walk-in','24-7','medicaid','no-insurance-ok']::text[], false, 'https://www.mountsinai.org/locations/urgent-care-east-14th-street'),
  ('doctors', 'mount-sinai-doctors-williamsburg', 'Mount Sinai Doctors Williamsburg', 'Primary care', 'A family medicine practice in North Williamsburg offering primary care, women''s health (Pap smears, birth control) and walk-in urgent non-emergency care, with evening and Saturday hours.', '135 N 7th St, Brooklyn, NY 11249', 'Williamsburg', 40.7194::float8, -73.959::float8, '6 from Spring St to 14 St–Union Sq, transfer to L to Bedford Av, walk 4 min.', '718-218-0450', 'https://www.mountsinai.org/locations/msd-williamsburg', 'Insurance accepted', ARRAY['walk-in','evening-hours','spanish']::text[], false, 'https://www.mountsinai.org/locations/msd-williamsburg'),
  ('doctors', 'mount-sinai-express-care-queens', 'Mount Sinai Express Care – Queens', 'Urgent & emergency', 'A walk-in urgent care in Astoria for minor illnesses and injuries, open daily including weekends; no appointment necessary.', '30-14 Crescent St, Long Island City, NY 11102', 'Astoria', 40.7686::float8, -73.9268::float8, '6 from Spring St to 59 St, transfer to N/W at Lexington Av/59 St to 30 Av, walk 5 min.', '718-808-7003', 'https://www.mountsinai.org/locations/queens/facilities/msq-express-care', 'All insurances accepted', ARRAY['walk-in','evening-hours']::text[], false, 'https://www.mountsinai.org/locations/queens/facilities/msq-express-care'),
  ('doctors', 'nyu-langone-cobble-hill-emergency', 'NYU Langone Emergency Department – Cobble Hill', 'Urgent & emergency', 'A 24/7 walk-in emergency department at Atlantic Avenue and Hicks Street, with on-site CT and X-ray and emergency-trained staff.', '70 Atlantic Ave, Brooklyn, NY 11201', 'Cobble Hill', 40.6911::float8, -73.9978::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, transfer to R to Court St, walk 9 min.', '646-754-7900', 'https://nyulangone.org/locations/home-depot-emergency-department-at-nyu-langone-health-cobble-hill', 'Insurance accepted; check with NYU Langone for billing', ARRAY['24-7','walk-in']::text[], false, 'https://nyulangone.org/locations/home-depot-emergency-department-at-nyu-langone-health-cobble-hill'),
  ('doctors', 'northwell-greenwich-village-hospital-er', 'Northwell Greenwich Village Hospital – Emergency Department', 'Urgent & emergency', 'A 24/7 emergency department on Seventh Avenue in the West Village, formerly known as Lenox Health Greenwich Village.', '30 7th Ave, New York, NY 10011', 'West Village', 40.7373::float8, -74.0003::float8, 'F or M from Delancey St–Essex St to 14 St, walk west 6 min.', '646-665-6000', 'https://gvh.northwell.edu', 'Emergency care billed to insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://gvh.northwell.edu/'),
  ('doctors', 'gouverneur-health-eye-care', 'NYC Health + Hospitals/Gouverneur – Eye Care', 'Dental & eye', 'Public-hospital eye clinic on the 4th floor of Gouverneur Health, a short trip from the Lower East Side. Open weekdays for eye exams and care.', '227 Madison St, 4th Floor, New York, NY 10002', 'Lower East Side', 40.7124::float8, -73.9874::float8, 'F from Delancey St–Essex St to East Broadway, walk 5 min.', '844-692-4492', 'https://www.nychealthandhospitals.org/gouverneur/', 'Public NYC Health + Hospitals clinic; call about insurance and financial assistance.', '{}'::text[], false, 'https://www.nyc.gov/assets/doh/downloads/pdf/scah/scah-vision-resource-list.pdf'),
  ('doctors', 'woodhull-hospital-emergency-department', 'NYC Health + Hospitals/Woodhull – Emergency Department', 'Urgent & emergency', 'Public-hospital emergency department in Bushwick/Williamsburg with separate adult, pediatric and psychiatric areas. New York State has designated it a Center of Excellence for sexual assault care.', '760 Broadway, Brooklyn, NY 11206', 'Williamsburg / Bushwick', 40.6997::float8, -73.9426::float8, 'J from Bowery to Flushing Av, walk 3 min.', NULL::text, 'https://www.nychealthandhospitals.org/woodhull/', 'Public hospital; serves patients regardless of insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://www.nyc.gov/html/hhc/woodhull/html/services/emergency.shtml'),
  ('doctors', 'nyp-lower-manhattan-hospital-er', 'NewYork-Presbyterian Lower Manhattan Hospital – Emergency Department', 'Urgent & emergency', 'A 24/7 emergency room in the Financial District, and the closest full hospital to the Lower East Side after Bellevue.', '170 William St, New York, NY 10038', 'Financial District', 40.7105::float8, -74.005::float8, 'J/Z from Bowery to Fulton St, walk 4 min.', '212-312-5000', 'https://www.nyp.org/lowermanhattan', 'Emergency care billed to insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://www.nyp.org/lowermanhattan'),
  ('doctors', 'brooklyn-hospital-center-emergency', 'The Brooklyn Hospital Center – Emergency Department', 'Urgent & emergency', 'Fort Greene''s 24/7 hospital emergency room, with a separate pediatric ER and multilingual staff.', '121 DeKalb Ave, Brooklyn, NY 11201', 'Fort Greene', 40.6905::float8, -73.9779::float8, 'B (weekdays) from Grand St to DeKalb Av, walk east 6 min.', '718-250-8075', 'https://www.tbh.org', 'Emergency care billed to insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://www.tbh.org/clinical-services/emergency-medicine'),
  ('doctors', 'nyp-brooklyn-methodist-emergency', 'NewYork-Presbyterian Brooklyn Methodist Hospital – Emergency Department', 'Urgent & emergency', 'Park Slope''s hospital emergency department, with a walk-in entrance on Seventh Avenue at Sixth Street.', '506 6th St, Brooklyn, NY 11215', 'Park Slope', 40.6683::float8, -73.9793::float8, 'F from Delancey St–Essex St to 7 Av (Brooklyn), walk 4 min.', '718-780-3000', 'https://www.nyp.org/brooklyn', 'Emergency care billed to insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://www.nyp.org/locations/brooklyn/nyp-brooklyn-methodist-hospital/directions'),
  ('doctors', 'mount-sinai-queens-emergency', 'Mount Sinai Queens – Emergency Department', 'Urgent & emergency', 'Astoria''s hospital emergency department, with a separate walk-in entrance on Crescent Street. Staff speak more than 35 languages.', '30-19 Crescent St, Astoria, NY 11102', 'Astoria', 40.768::float8, -73.9252::float8, 'J from Bowery to Canal St, transfer to the N to 30 Av (Astoria), walk west 7 min.', '718-932-1000', 'https://www.mountsinai.org/locations/queens', 'Emergency care billed to insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://www.mountsinai.org/locations/queens/care/emergency-medicine'),
  ('doctors', 'mount-sinai-morningside-emergency', 'Mount Sinai Morningside – Emergency Department', 'Urgent & emergency', 'A 24/7 emergency department near Columbia''s campus, with pediatric and psychiatric emergency departments in the same location.', '443 W 113th St, New York, NY 10025', 'Morningside Heights', 40.8055::float8, -73.9615::float8, 'B (weekdays) from Grand St to Cathedral Pkwy–110 St, walk northwest 8 min.', '212-636-3375', 'https://www.mountsinai.org/locations/morningside', 'Emergency care billed to insurance; ask about financial assistance.', ARRAY['24-7','walk-in']::text[], false, 'https://www.mountsinai.org/locations/morningside/care/emergency-services'),
  ('doctors', 'renfrew-center-nyc', 'The Renfrew Center of New York City', 'Nutrition', 'Eating-disorder treatment center near the Empire State Building offering day treatment, intensive outpatient and outpatient care, including nutrition counseling and services for college students. Virtual treatment is also available.', '349 Fifth Ave, 4th Floor, New York, NY 10016', 'Midtown / Murray Hill', 40.7484::float8, -73.9845::float8, 'B/D from Grand St to 34 St–Herald Sq, walk east 4 min.', '1-800-736-3739', 'https://renfrewcenter.com/locations/new-york-ny', 'Contact admissions about insurance coverage.', ARRAY['telehealth']::text[], false, 'https://renfrewcenter.com/locations/new-york-ny'),
  ('doctors', 'mount-sinai-eating-weight-disorders', 'Mount Sinai Center of Excellence in Eating and Weight Disorders', 'Nutrition', 'Mount Sinai''s eating-disorder program, offering outpatient and intensive outpatient treatment for anorexia, bulimia, binge eating disorder and ARFID.', '53 E 96th St, Suite 1A, New York, NY 10029', 'East Harlem / Upper East Side', 40.7873::float8, -73.9536::float8, '6 from Spring St to 96 St, walk west 4 min.', '212-659-8724', 'https://www.mountsinai.org/locations/eating-weight-disorders', 'Call about accepted insurance.', '{}'::text[], false, 'https://www.mountsinai.org/locations/eating-weight-disorders'),
  ('doctors', 'hss-sports-medicine-institute-west-side', 'HSS Sports Medicine Institute West Side', 'Physical therapy & sports medicine', 'Hospital for Special Surgery''s sports medicine center, bringing together sports medicine doctors, imaging, physical therapy and a sports rehab and performance center for active people at every level.', '610 W 58th St, New York, NY 10019', 'Hell''s Kitchen / Columbus Circle', 40.7714::float8, -73.9918::float8, 'B/D from Grand St to 59 St–Columbus Circle, walk west 10 min.', '646-885-8180', 'https://www.hss.edu/locations/ny/west-side', 'Most major insurance; call to confirm your plan.', '{}'::text[], false, 'https://www.hss.edu/locations/ny/west-side'),
  ('doctors', 'hss-womens-sports-medicine-center', 'HSS Women''s Sports Medicine Center', 'Physical therapy & sports medicine', 'Sports medicine center for active women from beginners to pros, with sports medicine doctors, physical therapy, nutrition and sports psychology. Common injuries it treats include stress fractures and ACL tears.', '535 E 70th St, New York, NY 10021', 'Upper East Side', 40.765::float8, -73.953::float8, '6 from Spring St to 68 St–Hunter College, walk east 10 min.', '212-606-1000', 'https://www.hss.edu/departments/sports-medicine/womens', 'Most major insurance; call to confirm your plan.', ARRAY['women-focused','beginner-friendly']::text[], false, 'https://www.hss.edu/departments/sports-medicine/womens'),
  ('doctors', 'rusk-rehabilitation-nyu-langone-orthopedic-center', 'Rusk Rehabilitation at NYU Langone Orthopedic Center', 'Physical therapy & sports medicine', 'NYU Langone''s outpatient rehabilitation site in Murray Hill, with physical therapists who specialize in sports injuries.', '333 E 38th St, New York, NY 10016', 'Murray Hill', 40.7464::float8, -73.973::float8, '6 from Spring St to 33 St, walk east 8 min.', '646-501-7070', 'https://nyulangone.org/locations/rusk-rehabilitation-at-nyu-langone-orthopedic-center', 'Most major insurance; call to confirm your plan.', '{}'::text[], false, 'https://nyulangone.org/locations/rusk-rehabilitation-at-nyu-langone-orthopedic-center'),
  ('doctors', 'weill-cornell-dermatology-downtown', 'Weill Cornell Medicine Dermatology – Downtown', 'Dermatology', 'Weill Cornell''s Financial District dermatology office, treating acne, hair loss, psoriasis and other skin conditions, and offering skin cancer screening.', '156 William St, 11th Floor, New York, NY 10038', 'Financial District', 40.7101::float8, -74.0063::float8, 'J/Z from Bowery to Fulton St, walk 3 min.', '646-962-3376', 'https://weillcornell.org/genderm', 'Most major insurance; call to confirm your plan.', '{}'::text[], false, 'https://weillcornell.org/genderm'),
  ('doctors', 'mount-sinai-skin-of-color-center', 'Mount Sinai Skin of Color Center', 'Dermatology', 'Mount Sinai dermatology center focused on skin conditions that affect people of color, such as acne, melasma, keloids, hair loss and vitiligo.', '5 E 98th St, 5th Floor, New York, NY 10029', 'East Harlem / Upper East Side', 40.7896::float8, -73.9545::float8, '6 from Spring St to 96 St, walk northwest 6 min.', '212-241-9728', 'https://www.mountsinai.org/locations/skin-color-center', 'Call about accepted insurance.', '{}'::text[], false, 'https://mountsinai.org/locations/skin-color-center'),
  ('doctors', 'charles-b-wang-walker-street-dental-eye', 'Charles B. Wang Community Health Center – Walker Street (Dental & Eye Care)', 'Dental & eye', 'Chinatown community health center offering dental care and primary eye care for adults and children, with multilingual staff. It''s a short walk or one stop from the Lower East Side.', '125 Walker St, 2nd Floor, New York, NY 10013', 'Chinatown', 40.7178::float8, -74.0003::float8, 'J/Z from Bowery to Canal St, walk 3 min.', '718-587-1111', 'https://www.cbwchc.org', 'Most insurance and Medicaid accepted; sliding fee discount for the uninsured and underinsured.', ARRAY['sliding-scale','medicaid','no-insurance-ok','chinese','spanish']::text[], false, 'https://www.cbwchc.org/find-doctors/dental-care'),
  ('doctors', 'suny-downstate-ophthalmology-brooklyn-heights', 'SUNY Downstate University Ophthalmic Consultants – Brooklyn Heights', 'Dental & eye', 'SUNY Downstate eye practice in downtown Brooklyn that offers urgent eye care on weekdays from 8 am to 5 pm, along with routine ophthalmology.', '26 Court St, Suite 1710, Brooklyn, NY 11242', 'Brooklyn Heights / Downtown Brooklyn', 40.6937::float8, -73.991::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, walk west 6 min.', '718-780-1530', 'https://www.downstate.edu/patient-care/find-treatment/areas-of-care/ophthalmology/', 'Call about accepted insurance.', '{}'::text[], false, 'https://www.downstate.edu/patient-care/find-treatment/areas-of-care/ophthalmology/services/urgent-care.html'),
  ('mental-health', 'university-settlement-consultation-center', 'University Settlement Consultation Center', 'Therapy', 'A community mental health clinic a few blocks from Broome St offering individual, couples, family and group therapy plus psychiatric care. Therapists speak English, Spanish, Mandarin, Cantonese, Korean and Hindi, with in-person, video and phone sessions.', '184 Eldridge St, New York, NY 10002', 'Lower East Side', 40.7203::float8, -73.9898::float8, '5-min walk north on Eldridge St', '(212) 453-4522', 'https://www.universitysettlement.org/programs/mental-health-wellness/consultation-center/', 'Medicaid, Medicare, some private insurance; sliding-scale self-pay', ARRAY['sliding-scale','medicaid','no-insurance-ok','spanish','chinese','telehealth','evening-hours']::text[], false, 'https://www.universitysettlement.org/programs/mental-health-wellness/consultation-center/'),
  ('mental-health', 'william-alanson-white-institute-clinical-services', 'William Alanson White Institute Clinical Services', 'Therapy', 'A psychoanalytic training institute that has run a low-cost treatment center since 1948, offering psychotherapy and psychoanalysis for adults. Specialty services include LGBTQ psychotherapy, eating disorders and compulsions, and therapy for artists.', '20 W 74th St, New York, NY 10023', 'Upper West Side', 40.7782::float8, -73.9757::float8, 'B (weekdays) from Grand St to 72 St, walk 3 min', '(212) 873-0725', 'https://wawhite.org/clinical-services/', 'Low-cost; fee set at intake', ARRAY['low-cost','lgbtq-affirming']::text[], false, 'https://wawhite.org/clinical-services/'),
  ('mental-health', 'karen-horney-clinic', 'The Karen Horney Clinic', 'Therapy', 'A nonprofit, state-licensed clinic founded in 1955 to offer low-cost psychotherapy and psychoanalysis. Fees are on a sliding scale, and many insurance plans are accepted, including Medicaid.', '329 E 62nd St, New York, NY 10065', 'Upper East Side', 40.7613::float8, -73.9606::float8, 'F from Delancey St–Essex St to Lexington Av/63 St, walk 6 min', '(212) 838-4333', 'https://www.karenhorneyclinic.org/', 'Sliding scale; most insurance incl. Medicaid', ARRAY['low-cost','sliding-scale','medicaid','evening-hours']::text[], false, 'https://www.karenhorneyclinic.org/location-hours'),
  ('mental-health', 'institute-for-contemporary-psychotherapy', 'Institute for Contemporary Psychotherapy (ICP)', 'Therapy', 'A training institute clinic near Columbus Circle offering individual therapy with income-based sliding-scale fees. Specialty services include LGBTQIA+-affirmative care, trauma, and eating disorder treatment with free support groups.', '33 W 60th St, 4th Floor, New York, NY 10023', 'Lincoln Square', 40.77::float8, -73.9822::float8, 'B/D from Grand St to 59 St–Columbus Circle, walk 2 min', '(212) 333-3444', 'https://icpnyc.org/', 'Sliding scale by income; some insurance incl. Emblem and Healthfirst Medicaid', ARRAY['sliding-scale','medicaid','lgbtq-affirming','telehealth','evening-hours']::text[], false, 'https://icpnyc.org/treatment/'),
  ('mental-health', 'nip-treatment-center', 'NIP Treatment Center (National Institute for the Psychotherapies)', 'Therapy', 'The clinic of a psychoanalytic training institute offering individual psychotherapy and EMDR trauma treatment, in person or by telehealth. Fees are set based on your income, expenses and insurance coverage.', '71 W 23rd St, Suite 1400, New York, NY 10010', 'Flatiron', 40.7429::float8, -73.9922::float8, 'F/M from Delancey St–Essex St to 23 St, walk 1 min', '(212) 582-1566', 'https://niptherapy.org/', 'Reduced fee based on income and expenses', ARRAY['sliding-scale','telehealth','lgbtq-affirming']::text[], false, 'https://niptherapy.org/'),
  ('mental-health', 'teachers-college-dean-hope-center', 'Dean Hope Center at Teachers College', 'Therapy', 'Teachers College, Columbia University''s training clinic is open to the public, with supervised trainees offering psychodynamic and interpersonal therapy. Services follow the academic calendar and trainee availability.', '525 W 120th St, 6th Floor, New York, NY 10027', 'Morningside Heights', 40.81::float8, -73.96::float8, 'B/D from Grand St to 59 St–Columbus Circle, transfer to 1 to 116 St–Columbia University, walk 5 min', '(212) 678-3262', 'https://www.tc.columbia.edu/deanhope/', '$40/session; sliding scale for financial hardship; no insurance accepted', ARRAY['low-cost','sliding-scale','no-insurance-ok']::text[], false, 'https://www.tc.columbia.edu/deanhope/services'),
  ('mental-health', 'identity-house-peer-counseling', 'Identity House', 'Support group', 'A volunteer-run nonprofit offering LGBTQ+ peer counseling for adults working through questions of sexual orientation and gender identity. It runs a walk-in center, short-term counseling, 8–10 week support groups and therapy referrals.', '208 W 13th St, New York, NY 10011', 'West Village', 40.7378::float8, -74.0009::float8, 'F/M from Delancey St–Essex St to 14 St, walk 4 min', NULL::text, 'https://identityhouse.org/', 'Volunteer peer counseling; ask about fees', ARRAY['lgbtq-affirming','walk-in','evening-hours','telehealth']::text[], false, 'https://identityhouse.org/'),
  ('mental-health', 'charles-b-wang-chc-mental-health-canal', 'Charles B. Wang Community Health Center – Mental Health (Canal St)', 'Therapy', 'A Chinatown community health center offering integrated mental health care, including psychotherapy and medication management, with staff who speak Chinese, Korean, Japanese and more. Mental health services are for established CBWCHC primary care patients, by referral from their provider.', '268 Canal St, New York, NY 10013', 'Chinatown', 40.7183::float8, -74.0013::float8, 'J/Z from Bowery to Canal St, walk 3 min', '(212) 941-2213', 'https://www.cbwchc.org/service/mental-health', 'Most insurance incl. Medicaid; sliding fee discount for uninsured', ARRAY['sliding-scale','medicaid','chinese']::text[], false, 'https://www.cbwchc.org/service/mental-health'),
  ('mental-health', 'apicha-chc-manhattan-behavioral-health', 'Apicha Community Health Center – Manhattan', 'Therapy', 'A community health center in lower Manhattan that offers behavioral and mental health care and psychiatry alongside primary care. Help with health insurance enrollment is available on site.', '400 Broadway, New York, NY 10013', 'Tribeca', 40.7187::float8, -74.0026::float8, 'J/Z from Bowery to Canal St, walk 4 min', '(212) 334-6029', 'https://www.apicha.org/locations/manhattan-clinic', 'Call for insurance and payment options', '{}'::text[], false, 'https://www.apicha.org/locations/manhattan-clinic'),
  ('mental-health', 'mount-sinai-savi-program', 'Mount Sinai Sexual Assault and Violence Intervention Program (SAVI)', 'Therapy', 'Free, confidential counseling for survivors of rape, sexual assault, child abuse and intimate partner violence, and for their friends and family. SAVI also offers emergency room and legal advocacy.', '1 Gustave L. Levy Pl, New York, NY 10029', 'East Harlem', 40.79::float8, -73.9526::float8, '6 from Spring St to 103 St, walk 6 min', '(212) 423-2140', 'https://www.mountsinai.org/care/obgyn/services/support-programs/savi', 'Free', ARRAY['free','confidential']::text[], true, 'https://mountsinai.org/patient-care/service-areas/community-medicine/sexual-assault-and-violence-intervention-program-savi/services'),
  ('mental-health', 'crime-victims-treatment-center', 'Crime Victims Treatment Center (CVTC)', 'Therapy', 'Supports survivors of sexual assault, intimate partner violence, childhood sexual abuse, trafficking and other violence. Services include crisis intervention, individual and group trauma-focused therapy, and legal advocacy.', '40 Exchange Pl, Suite 510, New York, NY 10005', 'Financial District', 40.7062::float8, -74.0099::float8, 'J/Z from Bowery to Broad St, walk 2 min', '(212) 523-4728', 'https://cvtcnyc.org/', 'Call to ask', '{}'::text[], false, 'https://cvtcnyc.org/en/contactus'),
  ('mental-health', 'samaritans-of-new-york-hotline', 'The Samaritans of New York Crisis Hotline', 'Crisis line', 'A local, confidential 24-hour emotional support and crisis line you can call or text, run by an NYC suicide prevention organization. Samaritans also offers a scheduled wellness check-in line and support for people who have lost someone to suicide.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, '(212) 673-3000', 'https://samaritansnyc.org/', 'Free', ARRAY['free','confidential','24-7']::text[], true, 'https://samaritansnyc.org/get-support/'),
  ('mental-health', 'ihi-therapy-center', 'IHI Therapy Center (Institute for Human Identity)', 'Therapy', 'Founded in 1973, this Chelsea center provides LGBTQ+-affirmative individual, couple and group therapy, including groups for trans and gender-diverse people and QTBIPOC communities. Sliding-scale fees are offered, and telehealth is available.', '322 8th Ave, Suite 802, New York, NY 10001', 'Chelsea', 40.7473::float8, -73.997::float8, 'F/M from Delancey St–Essex St to 23 St, walk 10 min west', NULL::text, 'https://ihitherapy.org/', 'Sliding scale; some private insurance', ARRAY['sliding-scale','lgbtq-affirming','telehealth']::text[], false, 'https://ihitherapy.org/'),
  ('mental-health', 'park-slope-center-for-mental-health', 'Park Slope Center for Mental Health', 'Therapy', 'A Brooklyn outpatient clinic offering individual therapy, family sessions, group support and psychiatry, in person or online. It accepts Medicaid and most major insurance plans.', '257 15th St, Brooklyn, NY 11215', 'Park Slope', 40.6644::float8, -73.9866::float8, 'F from Delancey St–Essex St to 7 Av (Brooklyn), walk 8 min', '(718) 788-5101', 'https://parkslopecenter.org/', 'Medicaid and most major insurance', ARRAY['medicaid','telehealth','evening-hours']::text[], false, 'https://parkslopecenter.org/'),
  ('mental-health', 'loveland-therapy-fund', 'Loveland Therapy Fund', 'Therapy', 'The Loveland Foundation helps Black women and nonbinary people pay for 4–12 therapy sessions with a provider found through its partner directories. The signup form opens quarterly, and there is a waitlist when it is closed.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://thelovelandfoundation.org/loveland-therapy-fund/', 'Covers 4–12 sessions for recipients', ARRAY['free','women-focused','telehealth']::text[], true, 'https://thelovelandfoundation.org/loveland-therapy-fund/'),
  ('mental-health', 'acmh-garden-house-crisis-respite', 'ACMH Garden House Crisis Respite', 'Crisis & drop-in center', 'A small East Village crisis respite where adults 18+ in emotional crisis can stay short-term with 24/7 support from trained peers, as an alternative to the ER. No diagnosis or insurance is needed; call 988 or the program to ask about availability.', '165 E 2nd St, New York, NY 10009', 'East Village', 40.7224::float8, -73.9846::float8, 'F from Delancey St–Essex St to 2 Av, walk 4 min (or 12-min walk)', '(212) 253-6377', 'https://www.nyc.gov/site/doh/health/health-topics/crisis-emergency-services-respite-centers.page', 'Insurance not required; regardless of ability to pay', ARRAY['no-insurance-ok','walk-in','24-7']::text[], false, 'https://www.nyc.gov/site/doh/health/health-topics/crisis-emergency-services-respite-centers.page'),
  ('mental-health', 'community-access-crisis-respite', 'Community Access Crisis Respite Center', 'Crisis & drop-in center', 'A quiet, home-like peer-run respite where adults in emotional crisis can stay for up to 28 days while continuing work or classes. No diagnosis or insurance is required.', '315 2nd Ave, New York, NY 10003', 'Gramercy', 40.7349::float8, -73.983::float8, '6 from Spring St to 23 St, walk 6 min', '(646) 257-5665', 'https://www.nyc.gov/site/doh/health/health-topics/crisis-emergency-services-respite-centers.page', 'Insurance not required; regardless of ability to pay', ARRAY['no-insurance-ok','walk-in','24-7']::text[], false, 'https://www.nyc.gov/site/doh/health/health-topics/crisis-emergency-services-respite-centers.page'),
  ('mental-health', 'sus-bright-corner-crisis-residence', 'S:US Bright Corner Crisis Residence', 'Crisis & drop-in center', 'A three-bed Williamsburg crisis residence for adults 18+, offering voluntary stays of 1–28 days with round-the-clock peer specialist support. Call to check bed availability.', '17-19 Montrose Ave, Brooklyn, NY 11206', 'Williamsburg', 40.7072::float8, -73.95::float8, 'J from Bowery to Lorimer St, walk 6 min', '(646) 757-4561', 'https://sus.org/crisisresidences/', 'Insurance not required; regardless of ability to pay', ARRAY['no-insurance-ok','walk-in','24-7']::text[], false, 'https://sus.org/crisisresidences/'),
  ('mental-health', 'metropolitan-center-for-mental-health-uws', 'Metropolitan Center for Mental Health – Upper West Side', 'Therapy', 'A nonprofit outpatient center offering therapy, medication management and telehealth for anxiety, depression, trauma and more. It accepts Medicaid and many other plans, and offers a sliding fee scale for uninsured patients.', '160 W 86th St, New York, NY 10024', 'Upper West Side', 40.7871::float8, -73.9737::float8, 'B (weekdays) from Grand St to 86 St, walk 3 min', '(646) 992-3357', 'https://www.mcmh.nyc/', 'Medicaid, Medicare and private insurance; sliding scale if uninsured', ARRAY['sliding-scale','medicaid','no-insurance-ok','telehealth','evening-hours']::text[], false, 'https://www.mcmh.nyc/'),
  ('mental-health', 'nyc-anti-violence-project', 'NYC Anti-Violence Project (AVP)', 'Crisis & drop-in center', 'Free counseling, advocacy and legal services for LGBTQ+ and HIV-affected survivors of hate violence, intimate partner violence and sexual violence. It has a bilingual English/Spanish hotline and weekday walk-in hours.', '55 Exchange Pl, Suite 404, New York, NY 10005', 'Financial District', 40.7061::float8, -74.0088::float8, 'J/Z from Bowery to Broad St, walk 3 min', '(212) 714-1141', 'https://avp.org/', 'Free', ARRAY['free','lgbtq-affirming','walk-in','spanish']::text[], true, 'https://avp.org/'),
  ('mental-health', 'blanton-peale-counseling-center', 'Blanton-Peale Counseling Center', 'Therapy', 'An outpatient training clinic in Midtown offering individual, couples, family and group therapy plus psychiatric care, in person or online. It is in network with most private plans and NYS Medicaid.', '7 W 30th St, 9th Floor, New York, NY 10001', 'NoMad', 40.7465::float8, -73.9867::float8, 'B/D from Grand St to 34 St–Herald Sq, walk 5 min', '(212) 725-7850', 'https://www.blantonpeale.org/', 'Most insurance incl. Medicaid; self-pay $125/session, groups $50', ARRAY['medicaid','telehealth']::text[], false, 'https://www.blantonpeale.org/counseling-center'),
  ('mental-health', 'new-york-intergroup-aa', 'New York Inter-Group of Alcoholics Anonymous', 'Support group', 'The central office for AA in the city, with a meeting finder for in-person and other meetings across NYC and a phone line staffed until 1am every day. The office and bookstore are in Chelsea.', '307 7th Ave, Suite 303, New York, NY 10001', 'Chelsea', 40.7471::float8, -73.9935::float8, 'B/D from Grand St to 34 St–Herald Sq, walk 7 min', '(212) 647-1680', 'https://www.nyintergroup.org/', 'See meeting finder', ARRAY['evening-hours']::text[], false, 'https://www.nyintergroup.org/'),
  ('mental-health', 'nyc-al-anon-family-intergroup', 'Greater NY Al-Anon Family Intergroup', 'Support group', 'Al-Anon meetings are for people whose lives have been affected by someone else''s drinking. You can talk or just listen, and meetings are anonymous and confidential; use the online finder to locate one nearby.', '247 W 37th St, Suite 11H, New York, NY 10018', 'Garment District', 40.7541::float8, -73.9905::float8, 'B/D from Grand St to 34 St–Herald Sq, walk 7 min', '(212) 941-0094', 'https://nycalanon.org/', 'See meeting finder', ARRAY['confidential']::text[], false, 'https://nycalanon.org/'),
  ('mental-health', 'trans-lifeline-hotline', 'Trans Lifeline Hotline', 'Crisis line', 'A peer support hotline staffed entirely by trans and nonbinary operators. They will not call emergency services or law enforcement without your explicit request.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, '(877) 565-8860', 'https://translifeline.org/hotline/', 'No cost listed', ARRAY['lgbtq-affirming','confidential']::text[], false, 'https://translifeline.org/hotline/'),
  ('mental-health', 'nys-hopeline', 'NYS HOPEline', 'Crisis line', 'New York State''s free, confidential 24/7 call-and-text line for substance use and gambling concerns. Trained staff offer crisis support and referrals to treatment, support groups and peer support.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, '1-877-846-7369', 'https://oasas.ny.gov/hopeline', 'Free', ARRAY['free','confidential','24-7','spanish','chinese']::text[], true, 'https://oasas.ny.gov/hopeline'),
  ('mental-health', 'korean-american-family-service-center-hotline', 'Korean American Family Service Center 24-Hour Hotline', 'Crisis line', 'A bilingual Korean/English 24-hour hotline for people experiencing domestic violence or sexual assault, from an organization serving Korean and Asian American immigrant communities. KAFSC also provides counseling, advocacy and shelter support.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, '(718) 460-3800', 'https://www.kafsc.org/', 'Call for details', ARRAY['24-7']::text[], false, 'https://www.kafsc.org/'),
  ('mental-health', 'postpartum-support-international-helpline', 'Postpartum Support International HelpLine', 'Support group', 'A free, confidential call-or-text helpline in English and Spanish for anyone struggling during pregnancy or after birth; a trained volunteer returns your message. PSI also runs more than 50 free online support groups.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, '1-800-944-4773', 'https://www.postpartum.net/get-help/', 'Free', ARRAY['free','confidential','spanish','women-focused','telehealth']::text[], true, 'https://www.postpartum.net/get-help/'),
  ('mental-health', 'asian-mental-health-collective', 'Asian Mental Health Collective', 'Therapy', 'Online resources for Asian communities, including a directory of 3,000+ Asian therapists and virtual community support groups. Its free therapy fund covers 16 sessions over six months for selected applicants.', NULL::text, 'Phone / online', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.asianmhc.org/', 'Support groups and therapy fund free; directory therapists set their own fees', ARRAY['free','telehealth']::text[], false, 'https://www.asianmhc.org/'),
  ('resources', 'nypl-schwarzman-building', 'NYPL Stephen A. Schwarzman Building', 'Library', 'The New York Public Library''s landmark research library on Fifth Avenue, with free admission, reading rooms and exhibitions. The Rose Main Reading Room has a visiting hour Monday–Saturday mornings plus free short tours.', '476 Fifth Ave, New York, NY 10018', 'Midtown', 40.7532::float8, -73.9822::float8, 'B/D from Grand St to 42 St–Bryant Park, 3-min walk', NULL::text, 'https://www.nypl.org/locations/schwarzman', 'Free', ARRAY['free','student-friendly','evening-hours']::text[], true, 'https://m.nypl.org/locations/schwarzman/visitor-center'),
  ('resources', 'nypl-stavros-niarchos-foundation-library', 'NYPL Stavros Niarchos Foundation Library (SNFL)', 'Library', 'NYPL''s largest circulating library, across from the Schwarzman Building, with long weekday hours (open until 9 pm Mon–Thu) and lots of seating for studying. Free with or without a library card.', '455 Fifth Ave, New York, NY 10016', 'Midtown', 40.7518::float8, -73.9814::float8, 'B/D from Grand St to 42 St–Bryant Park, 3-min walk', NULL::text, 'https://www.nypl.org/locations/snfl', 'Free', ARRAY['free','student-friendly','evening-hours']::text[], true, 'https://dev-www.nypl.org/locations/snfl/read'),
  ('resources', 'nypl-mulberry-street-library', 'NYPL Mulberry Street Library', 'Library', 'A neighborhood NYPL branch in a converted 1886 chocolate factory, with two lower levels of reading space and about 45 public computers and laptops. Closed Sundays.', '10 Jersey St, New York, NY 10012', 'Nolita / SoHo', 40.7244::float8, -73.9958::float8, 'B/D from Grand St to Broadway–Lafayette St, 3-min walk (or about a 12-min walk)', '(212) 966-3424', 'https://www.nypl.org/locations/mulberry-street', 'Free', ARRAY['free','student-friendly']::text[], true, 'https://live-legacy-admin.nypl.org/about/locations/mulberry-street'),
  ('resources', 'bpl-central-library', 'Brooklyn Public Library – Central Library', 'Library', 'Brooklyn''s flagship library at Grand Army Plaza, with the Shelby White & Leon Levy Information Commons co-working space and reservable meeting rooms. Open until 8 pm Monday–Thursday.', '10 Grand Army Plaza, Brooklyn, NY 11238', 'Prospect Heights', 40.6725::float8, -73.9681::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, transfer to 2/3 to Grand Army Plaza', '(718) 230-2100', 'https://www.bklynlibrary.org/locations/central', 'Free', ARRAY['free','student-friendly','evening-hours']::text[], true, 'https://www.bklynlibrary.org/locations/central'),
  ('resources', 'bpl-greenpoint-library', 'Brooklyn Public Library – Greenpoint Library and Environmental Education Center', 'Library', 'A 15,000-square-foot branch with adult and teen spaces, laptop loans, meeting rooms and printing, plus environmental programming and a demonstration garden. Open until 8 pm Tuesdays and Thursdays.', '107 Norman Ave, Brooklyn, NY 11222', 'Greenpoint', 40.7262::float8, -73.9497::float8, 'J/M from Delancey St–Essex St to Lorimer St, short walk to Broadway for the G to Nassau Av, 4-min walk', '(718) 389-4394', 'https://www.bklynlibrary.org/locations/greenpoint', 'Free', ARRAY['free','student-friendly','evening-hours']::text[], true, 'https://www.bklynlibrary.org/locations/greenpoint'),
  ('resources', 'qpl-long-island-city-library', 'Queens Public Library – Long Island City', 'Library', 'A Queens Public Library branch with free Wi-Fi, computer workstations, remote printing, an Adult Learning Center and a Teen Center. Closed Sundays and Mondays; open until 8 pm Thursdays.', '37-44 21st St, Long Island City, NY 11101', 'Long Island City', 40.7588::float8, -73.9387::float8, 'F from Delancey St–Essex St to 21 St–Queensbridge, 6-min walk', '(718) 752-3700', 'https://www.queenslibrary.org/about-us/locations/long-island-city', 'Free', ARRAY['free','student-friendly','evening-hours']::text[], true, 'https://www.queenslibrary.org/about-us/locations/long-island-city'),
  ('resources', 'qpl-sunnyside-library', 'Queens Public Library – Sunnyside', 'Library', 'A neighborhood Queens Public Library branch with free Wi-Fi, computer workstations, classes and programs. Closed Sundays and Mondays; open until 8 pm Thursdays.', '43-06 Greenpoint Ave, Long Island City, NY 11104', 'Sunnyside', 40.7417::float8, -73.923::float8, 'B/D from Grand St to 42 St–Bryant Park, transfer to the 7 at 5 Av to 40 St–Lowery St, 5-min walk', '(718) 784-3033', 'https://www.queenslibrary.org/about-us/locations/sunnyside', 'Free', ARRAY['free','student-friendly','evening-hours']::text[], true, 'https://www.queenslibrary.org/about-us/locations/sunnyside'),
  ('resources', 'brooklyn-family-justice-center', 'Brooklyn Family Justice Center', 'Safety & legal', 'A City-run center offering free, confidential help for survivors of domestic violence, elder abuse and sex trafficking, with legal, social and criminal justice services in one place. Walk-ins welcome Mon–Fri 9 am–5 pm; childcare for kids 3+ while you meet with staff.', '350 Jay St, Brooklyn, NY 11201', 'Downtown Brooklyn', 40.6935::float8, -73.9873::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, 2-min walk', '(718) 250-5111', 'https://www.nyc.gov/site/ocdv/programs/family-justice-centers.page', 'Free', ARRAY['free','confidential','walk-in','women-focused']::text[], true, 'https://portal.311.nyc.gov/article/?kanumber=KA-02084'),
  ('resources', 'sanctuary-for-families', 'Sanctuary for Families', 'Safety & legal', 'A nonprofit serving survivors of domestic violence, sex trafficking and related gender violence, with counseling, legal services (family, immigration and trafficking law), shelter and economic empowerment programs. You can call or use the live chat on their website.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '(212) 349-6009', 'https://sanctuaryforfamilies.org/', 'Free', ARRAY['free','women-focused','confidential']::text[], true, 'https://sanctuaryforfamilies.org/contact/'),
  ('resources', 'womankind-helpline', 'Womankind', 'Safety', 'Free, confidential help for survivors of domestic violence, sexual violence and human trafficking, with a focus on Asian communities but open to all. Its 24/7 helpline offers support in 18+ Asian languages and dialects, English and Spanish; text lines are available in English and Chinese.', '42 Broadway, Suite 1836, New York, NY 10004', 'Financial District', 40.7058::float8, -74.0128::float8, 'J/Z from Bowery to Broad St, 5-min walk', '1-888-888-7702', 'https://www.iamwomankind.org/', 'Free', ARRAY['free','confidential','24-7','women-focused','chinese','spanish']::text[], true, 'https://www.iamwomankind.org/'),
  ('resources', 'legal-aid-society', 'The Legal Aid Society', 'Legal help', 'NYC''s largest provider of free legal services for low-income New Yorkers, covering housing, immigration, family law and domestic violence, employment, public benefits and LGBTQ+ issues. Call the main line to get connected; offices operate in every borough.', '199 Water St, New York, NY 10038', 'Financial District', 40.7072::float8, -74.0029::float8, 'J/Z from Bowery to Fulton St, 5-min walk', '(212) 577-3300', 'https://legalaidnyc.org/', 'Free for eligible low-income New Yorkers', ARRAY['free']::text[], true, 'https://legalaidnyc.org/office/legal-aid-society-headquarters/'),
  ('resources', 'nylag-new-york-legal-assistance-group', 'New York Legal Assistance Group (NYLAG)', 'Legal help', 'Free civil legal services and financial counseling in areas including immigration, housing, employment, domestic violence, LGBTQ+ rights and public benefits. In-office meetings are by appointment only after completing intake.', '100 Pearl St, 19th Floor, New York, NY 10004', 'Financial District', 40.704::float8, -74.0101::float8, 'J/Z from Bowery to Broad St, 5-min walk', '(212) 613-5000', 'https://nylag.org/', 'Free for eligible clients', ARRAY['free','lgbtq-affirming']::text[], true, 'https://nylag.org/contact-us/'),
  ('resources', 'housing-court-answers-hotline', 'Housing Court Answers', 'Housing', 'A free hotline for tenants with questions about Housing Court, landlord-tenant rules and rent assistance, plus referrals to legal services. Hotline hours are Mon–Fri 9 am–5 pm, and staff run information tables in the Manhattan, Brooklyn and Queens housing courts.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '(212) 962-4795', 'https://housingcourtanswers.org/', 'Free', ARRAY['free']::text[], true, 'https://housingcourtanswers.org/contact-us/'),
  ('resources', 'nyc-tenant-helpline', 'NYC Tenant Helpline (via 311)', 'Housing', 'Call 311 and ask for the "Tenant Helpline" to learn your rights as a renter and get connected to free legal services, mediation and benefits referrals. Live specialists are available Mon–Fri 9:30 am–5 pm, regardless of immigration status.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '311', 'https://www.nyc.gov/site/mayorspeu/resources/tenant-helpline.page', 'Free', ARRAY['free']::text[], true, 'https://www.nyc.gov/site/mayorspeu/resources/tenant-helpline.page'),
  ('resources', 'goles-lower-east-side', 'GOLES (Good Old Lower East Side)', 'Housing', 'A neighborhood housing organization helping Lower East Side/Loisaida residents with eviction prevention and tenant rights, plus workforce development and other services. Open Mon–Fri 10 am–6 pm; serves the area south of 14th St and east of 4th Ave/the Bowery.', '169 Avenue B, New York, NY 10009', 'East Village / Loisaida', 40.7272::float8, -73.979::float8, 'F from Delancey St–Essex St to 2 Av, then about a 15-min walk northeast', NULL::text, 'https://www.goles.org/', 'Free', ARRAY['free']::text[], true, 'https://www.goles.org/'),
  ('resources', 'moia-immigration-legal-support-hotline', 'NYC Immigration Legal Support Hotline (MOIA)', 'Legal help', 'A free, City-funded hotline that answers immigration questions and connects New Yorkers to trusted immigration legal help in their language, Mon–Fri 9 am–6 pm. Anyone can call; to receive legal services you must be an NYC resident with income at or below 200% of the federal poverty level.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '(800) 354-0365', 'https://www.nyc.gov/site/immigrants/legal-resources/get-legal-help.page', 'Free', ARRAY['free','confidential']::text[], true, 'https://www.nyc.gov/site/immigrants/legal-resources/get-legal-help.page'),
  ('resources', 'cuny-citizenship-now', 'CUNY Citizenship Now!', 'Legal help', 'Free, confidential immigration law services for all New Yorkers, CUNY students or not, regardless of income, including help with citizenship, DACA, TPS, family petitions and fee waivers. Call to schedule an appointment at a center near you.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '(646) 664-9400', 'https://www.cuny.edu/about/administration/offices/communications-marketing/citizenship-now/', 'Free (USCIS fees may apply; fee-waiver help available)', ARRAY['free','student-friendly','confidential']::text[], true, 'https://www.cuny.edu/about/administration/offices/communications-marketing/citizenship-now/'),
  ('resources', 'make-the-road-ny-bushwick', 'Make the Road New York – Bushwick', 'Legal help', 'A community organization offering legal help with immigration (including citizenship and asylum), employment and wage theft, housing and tenant rights, and TGNCIQ rights such as name changes. Spanish-language services are available.', '301 Grove St, Brooklyn, NY 11237', 'Bushwick', 40.6958::float8, -73.9165::float8, 'M from Delancey St–Essex St to Knickerbocker Av, 5-min walk', '(718) 418-7690', 'https://maketheroadny.org/', 'Contact for details', ARRAY['spanish','lgbtq-affirming']::text[], false, 'https://maketheroadny.org/legal-services/'),
  ('resources', 'holy-apostles-soup-kitchen', 'Holy Apostles Soup Kitchen & Pantry', 'Food', 'A free hot meal Mon–Fri 10:30 am–12:30 pm with an open-door policy: everyone is welcome, no questions asked. The pantry hands out grocery bags with dry goods and produce Tue–Thu, 9:30–11 am and 1:30–3 pm.', '296 9th Ave, New York, NY 10001', 'Chelsea', 40.7497::float8, -73.9993::float8, 'B/D from Grand St to 34 St–Herald Sq, 12-min walk west', '(212) 924-0167', 'https://holyapostlesnyc.org/', 'Free', ARRAY['free','walk-in']::text[], true, 'https://holyapostlesnyc.org/'),
  ('resources', 'st-johns-bread-and-life', 'St. John''s Bread & Life', 'Food', 'A Bed-Stuy food program with a digital choice food pantry (fresh produce, dairy, meat and staples), grab-and-go meals, plus case management, health and legal services. Register for food through their website.', '795 Lexington Ave, Brooklyn, NY 11221', 'Bed-Stuy', 40.6928::float8, -73.9305::float8, 'J from Bowery to Kosciuszko St, 3-min walk', '(718) 574-0058', 'https://www.breadandlife.org/', 'Free', ARRAY['free']::text[], true, 'https://www.breadandlife.org/'),
  ('resources', 'chips-park-slope', 'CHiPS (Community Help in Park Slope)', 'Food', 'Free community meals Monday–Saturday (breakfast 9–10:30 am, lunch 11:30 am–1 pm) and a take-home food pantry Thursdays and Saturdays 11:30 am–1 pm.', '200 4th Ave, Brooklyn, NY 11217', 'Park Slope', 40.6795::float8, -73.9823::float8, 'D from Grand St to Atlantic Av–Barclays Ctr, transfer to R to Union St, 2-min walk', NULL::text, 'https://www.chipsonline.org/', 'Free', ARRAY['free','walk-in']::text[], true, 'https://www.chipsonline.org/get-services'),
  ('resources', 'nyc-financial-empowerment-centers', 'NYC Financial Empowerment Centers', 'Money & career', 'Free, confidential one-on-one financial counseling (in person or by phone) for budgeting, credit, opening a safe bank account and tackling debt, including student loans. Open to anyone 18+ who lives or works in NYC; book online or call.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '(212) 487-4583', 'https://access.nyc.gov/programs/nyc-financial-empowerment-centers/', 'Free', ARRAY['free','confidential','student-friendly']::text[], true, 'https://access.nyc.gov/programs/nyc-financial-empowerment-centers/'),
  ('resources', 'nyc-free-tax-prep', 'NYC Free Tax Prep', 'Money & career', 'Free tax filing with IRS-certified volunteer preparers for people who live or work in NYC. For 2025 taxes, the limit was $68,000 or less in income without dependents ($97,000 with dependents); sites open during tax season.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '311', 'https://www.nyc.gov/site/dca/talk-money/file-your-taxes-faqs.page', 'Free for income-eligible filers', ARRAY['free','student-friendly']::text[], true, 'https://www.nyc.gov/site/dca/talk-money/file-your-taxes-faqs.page'),
  ('resources', 'workforce1-brooklyn-career-center', 'Brooklyn Workforce1 Career Center', 'Money & career', 'A City career center offering personalized career counseling, résumé and cover letter help, interview advice, workshops and connections to training and jobs.', '9 Bond St, 5th Floor, Brooklyn, NY 11201', 'Downtown Brooklyn', 40.6904::float8, -73.9837::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, 5-min walk', NULL::text, 'https://www.nyc.gov/site/sbs/careers/wf1-career-centers.page', 'Free', ARRAY['free','beginner-friendly']::text[], true, 'https://www.nyc.gov/site/sbs/careers/wf1-career-centers.page'),
  ('resources', 'idnyc', 'IDNYC', 'City services', 'NYC''s free government-issued ID card for residents 10 and up, regardless of immigration status. It comes with a year of free memberships at 35+ museums, zoos and gardens. Book an appointment online or via 311; some centers take walk-ins on set days, including Manhattan Union Square on Thursdays.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '311', 'https://www.nyc.gov/site/idnyc/card/how-to-apply.page', 'Free (for applications through Dec 31, 2026)', ARRAY['free','student-friendly']::text[], true, 'https://www.nyc.gov/site/idnyc/frequently-asked-questions/frequently-asked-questions.page'),
  ('resources', 'culture-pass-nyc', 'Culture Pass', 'Culture', 'Reserve free admission to 100+ NYC museums, gardens and cultural venues using a Brooklyn, New York or Queens Public Library card (ages 13+). You can get a library card if you live in New York State or work or study in NYC.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.culturepass.nyc/', 'Free with a library card', ARRAY['free','student-friendly']::text[], true, 'https://www.culturepass.nyc/'),
  ('resources', 'the-met-fifth-avenue', 'The Metropolitan Museum of Art (The Met Fifth Avenue)', 'Culture', 'New York State residents and students from New York, New Jersey and Connecticut can pay what they wish, with a minimum of $0.01. Bring a student ID or proof of NY residency (an IDNYC or NY library card counts).', '1000 Fifth Ave, New York, NY 10028', 'Upper East Side', 40.7794::float8, -73.9632::float8, '6 from Spring St to 86 St, 10-min walk west', NULL::text, 'https://www.metmuseum.org/plan-your-visit', 'Pay what you wish for NY residents & NY/NJ/CT students; $17 other students', ARRAY['low-cost','student-friendly']::text[], false, 'https://www.metmuseum.org/plan-your-visit'),
  ('resources', 'moma-uniqlo-friday-nights', 'MoMA – UNIQLO Friday Nights', 'Culture', 'The Museum of Modern Art is free for New York State residents every Friday from 5:30 to 8:30 pm. Reserve tickets in advance (released a week ahead) and bring proof of residency.', '11 W 53rd St, New York, NY 10019', 'Midtown', 40.7614::float8, -73.9776::float8, 'M from Delancey St–Essex St to 5 Av/53 St, 2-min walk', NULL::text, 'https://www.moma.org/visit', 'Free Fri 5:30–8:30 pm for NY State residents; $17 students otherwise', ARRAY['free','student-friendly','evening-hours']::text[], false, 'https://www.moma.org/calendar/events/10253'),
  ('resources', 'whitney-museum', 'Whitney Museum of American Art', 'Culture', 'Free admission for visitors 25 and under, plus Free Friday Nights for everyone from 5 to 10 pm. Otherwise, student tickets are $24. Closed Tuesdays.', '99 Gansevoort St, New York, NY 10014', 'Meatpacking District', 40.7396::float8, -74.0089::float8, 'M from Delancey St–Essex St to 14 St (6 Av), 12-min walk west', NULL::text, 'https://whitney.org/visit', 'Free for 25 and under; free Fri 5–10 pm; $24 students', ARRAY['free','student-friendly','evening-hours']::text[], false, 'https://whitney.org/visit'),
  ('resources', 'brooklyn-museum', 'Brooklyn Museum', 'Culture', 'General admission is a suggested contribution, so you can pay what you can at the admissions desk; students 20+ are suggested $14 and visitors 19 and under are free. Free First Saturdays evening events (registration required) run in select months.', '200 Eastern Pkwy, Brooklyn, NY 11238', 'Prospect Heights', 40.6712::float8, -73.9636::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, transfer to 2/3 to Eastern Pkwy–Brooklyn Museum', NULL::text, 'https://www.brooklynmuseum.org/visit', 'Pay what you can (suggested $14 students)', ARRAY['low-cost','student-friendly']::text[], false, 'https://www.brooklynmuseum.org/visit'),
  ('resources', 'new-museum-bowery', 'New Museum', 'Culture', 'A contemporary art museum on the Bowery, a few minutes'' walk from Broome St, which reopened in March 2026 with an expanded building. Admission is pay what you wish Thursdays 7–9 pm (reserve online); student tickets are $19, and NYU and Pratt students get in free.', '235 Bowery, New York, NY 10002', 'Lower East Side', 40.7224::float8, -73.9927::float8, 'About a 4-min walk', NULL::text, 'https://www.newmuseum.org/visit/', 'Pay what you wish Thu 7–9 pm; $19 students', ARRAY['low-cost','student-friendly','evening-hours']::text[], false, 'https://www.newmuseum.org/visit/free-admission/'),
  ('resources', 'getcoverednyc', 'GetCoveredNYC', 'Health coverage', 'Free one-on-one help finding and enrolling in health insurance, in 23+ languages, regardless of immigration status or income. Call 311 and say "GetCoveredNYC," or text CoveredNYC to 55676.', NULL::text, 'Citywide', NULL::float8, NULL::float8, NULL::text, '311', 'https://www.nyc.gov/site/mayorspeu/programs/getcoverednyc.page', 'Free', ARRAY['free','no-insurance-ok','student-friendly']::text[], true, 'https://www.nyc.gov/site/mayorspeu/programs/getcoverednyc.page'),
  ('clubs', 'housing-works-bookstore-cafe', 'Housing Works Bookstore Cafe', 'Books & events', 'A long-running SoHo used bookstore and cafe whose profits fund Housing Works'' HIV/AIDS and homelessness services. Regular volunteers can help run the store and get a discount where they volunteer.', '126 Crosby St, New York, NY 10012', 'SoHo', 40.7246::float8, -73.9965::float8, 'B/D from Grand St to Broadway–Lafayette St (1 stop), 2 min walk', '212-334-3324', 'https://www.housingworks.org/locations/bookstore-cafe', 'Free to browse; secondhand books and cafe items for sale', ARRAY['walk-in']::text[], false, 'https://www.housingworks.org/locations/bookstore-cafe'),
  ('clubs', 'books-are-magic-cobble-hill', 'Books Are Magic', 'Books & events', 'Independent bookstore founded by novelist Emma Straub, with a busy calendar of author events and readings.', '225 Smith St, Brooklyn, NY 11231', 'Cobble Hill', 40.6857::float8, -73.9918::float8, 'F from Delancey St–Essex St to Bergen St, 3 min walk', NULL::text, 'https://www.booksaremagic.net', 'Free to browse; check event listings for details', '{}'::text[], false, 'https://www.booksaremagic.net/events'),
  ('clubs', 'greenlight-bookstore-fort-greene', 'Greenlight Bookstore', 'Book club', 'Fort Greene indie bookstore that hosts author events and runs in-store book clubs, including Fiction, Queer, Young Adult and Tween groups.', '686 Fulton St, Brooklyn, NY 11217', 'Fort Greene', 40.6866::float8, -73.9746::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, 8 min walk', NULL::text, 'https://www.greenlightbookstore.com', 'Free to browse; check site for book club and event details', ARRAY['lgbtq-affirming']::text[], false, 'https://www.greenlightbookstore.com/'),
  ('clubs', 'cafe-con-libros-crown-heights', 'Café con Libros', 'Books & events', 'Intersectional feminist community bookstore and coffee shop centering women, girls and non-binary folks. Founded by an Afro-Latina veteran, it hosts community events (contact events@cafeconlibrosbk.com).', '724 Prospect Pl, Brooklyn, NY 11216', 'Crown Heights', 40.6744::float8, -73.9519::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, transfer to 2/3 to Nostrand Av, 6 min walk', NULL::text, 'https://www.cafeconlibrosbk.com', 'Free to browse; books and coffee for sale', ARRAY['women-focused','lgbtq-affirming']::text[], false, 'https://www.cafeconlibrosbk.com/'),
  ('clubs', 'book-club-bar-east-village', 'Book Club Bar', 'Books & events', 'East Village independent bookstore with a coffee and cocktail bar and plenty of cozy seating. It''s laptop-free after 7pm and on weekends to encourage conversation, and there''s a second location in Bushwick.', '197 E 3rd St, New York, NY 10009', 'East Village', 40.7225::float8, -73.9839::float8, 'F from Delancey St–Essex St to 2 Av, 6 min walk (or about a 15 min walk)', NULL::text, 'https://www.bookclubbar.com', 'Free to browse; drinks and books for sale', ARRAY['evening-hours']::text[], false, 'https://bookshop.org/shop/bookclubbar'),
