  ('clubs', 'asian-american-writers-workshop', 'Asian American Writers'' Workshop', 'Books & events', 'Literary nonprofit that has championed Asian and Asian diaspora writing since 1991, with readings, events and multi-week writing workshops.', '18 W 21st St, Suite 900, New York, NY 10010', 'Flatiron', 40.7409::float8, -73.992::float8, 'F/M from Delancey St–Essex St to 23 St, 4 min walk', NULL::text, 'https://aaww.org', 'Varies by event; check site', '{}'::text[], false, 'https://aaww.org/'),
  ('clubs', 'nuyorican-poets-cafe', 'Nuyorican Poets Cafe', 'Books & events', 'Legendary Loisaida poetry venue whose open mics, poetry slams and monthly Womxn Orator Wednesday nights are running at venues around the Lower East Side and online while its home theater at 236 E 3rd St is renovated.', NULL::text, 'Lower East Side (rotating venues)', NULL::float8, NULL::float8, NULL::text, '212-780-9386', 'https://www.nuyorican.org', 'Varies by event; check site', '{}'::text[], false, 'https://www.nuyorican.org/'),
  ('clubs', 'liz-christy-community-garden', 'Liz Christy Community Garden', 'Gardening', 'New York City''s first community garden, a few blocks away on Houston St. Visitors and volunteers are welcome during open hours, and volunteers can work toward a key and full membership.', 'E Houston St & Bowery, New York, NY 10012', 'Lower East Side / NoHo', 40.7243::float8, -73.9918::float8, 'About a 7 min walk north via Chrystie St', NULL::text, 'https://www.lizchristygarden.us', 'Free', ARRAY['free','outdoor']::text[], true, 'https://www.lizchristygarden.us/'),
  ('clubs', '6bc-botanical-garden', '6BC Botanical Garden', 'Gardening', 'Volunteer-run East Village community garden that is open to visitors on weekend afternoons from April through October, with membership and volunteer opportunities.', '624 E 6th St, New York, NY 10009', 'East Village', 40.7236::float8, -73.9808::float8, 'F from Delancey St–Essex St to 2 Av, 10 min walk', NULL::text, 'https://www.6bcgarden.org', 'Free to visit; see site for membership', ARRAY['free','outdoor']::text[], true, 'https://www.6bcgarden.org/visit'),
  ('clubs', 'battery-urban-farm-volunteers', 'The Battery Urban Farm & Gardens Volunteers', 'Gardening', 'Help harvest, compost, plant and weed at the Battery Urban Farm or tend the perennial gardens alongside professional horticulturists. Morning shifts run March through October after an online orientation.', 'State St & Battery Pl, New York, NY 10004', 'Battery Park', 40.7036::float8, -74.0153::float8, 'J/Z from Bowery to Broad St, 8 min walk', NULL::text, 'https://www.thebattery.org/volunteer/', 'Free for individuals', ARRAY['free','outdoor']::text[], true, 'https://www.thebattery.org/volunteer/'),
  ('clubs', 'brooklyn-bridge-park-green-team', 'Brooklyn Bridge Park Green Team', 'Gardening', 'Twice-monthly Saturday morning gardening sessions (weeding, mulching, leaf removal) in Brooklyn Bridge Park from April through October. No gardening experience is needed.', 'Brooklyn Bridge Park, Brooklyn, NY 11201', 'DUMBO / Brooklyn Heights', 40.7003::float8, -73.9967::float8, 'F from Delancey St–Essex St to York St, 10 min walk', NULL::text, 'https://www.brooklynbridgepark.org/volunteer/', 'Free', ARRAY['free','outdoor','beginner-friendly']::text[], true, 'https://www.brooklynbridgepark.org/volunteer/'),
  ('clubs', 'prospect-park-alliance-volunteers', 'Prospect Park Alliance Volunteers', 'Volunteering', 'Weekend Park Pitch In projects such as tree care, invasive plant removal and litter cleanup, plus seasonal Fall Fix Up days. Register through the volunteer portal.', 'Prospect Park, Brooklyn, NY 11215', 'Prospect Park', 40.6602::float8, -73.969::float8, 'B (weekdays) from Grand St to Prospect Park; or D to Atlantic Av–Barclays Ctr and transfer to Q', '929-888-6826', 'https://www.prospectpark.org/get-involved/volunteer/', 'Free', ARRAY['free','outdoor']::text[], true, 'https://www.prospectpark.org/get-involved/volunteer/'),
  ('clubs', 'lower-east-side-ecology-center', 'Lower East Side Ecology Center', 'Volunteering', 'Neighborhood environmental nonprofit that runs composting and recycling services, stewardship projects and educational programs, with volunteer opportunities. Its learning center is in Seward Park.', 'Seward Park, Essex St & Canal St, New York, NY 10002', 'Lower East Side', 40.7142::float8, -73.9895::float8, 'About an 8 min walk southeast', '212-477-4022', 'https://www.lesecologycenter.org', 'Free to volunteer', ARRAY['free','outdoor']::text[], true, 'https://www.lesecologycenter.org/'),
