  ('clubs', 'girls-write-now-mentors', 'Girls Write Now', 'Volunteering', 'NYC-rooted writing and mentoring organization that pairs mentors with young writers, focusing on those historically disempowered because of gender or gender identity. Programs include virtual offerings and in-person events.', NULL::text, 'Citywide / virtual', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://girlswritenow.org', 'Free to volunteer', ARRAY['free','women-focused','lgbtq-affirming']::text[], true, 'https://girlswritenow.org/'),
