  ('workouts', 'mendez-boxing-harlem', 'Mendez Boxing', 'Boxing', 'A Harlem boxing gym with trainer-led and self-directed options for fitness boxers and competitors alike. Day passes make it easy to try.', '56 W 125th St, New York, NY 10027', 'Harlem', 40.8067::float8, -73.9447::float8, 'B/D from Grand St to 125 St, then walk east (~10 min)', '917-837-1742', 'https://www.mendezboxinggym.com/', 'Self-directed day pass $25; with trainer $39', ARRAY['walk-in','evening-hours']::text[], false, 'https://www.mendezboxinggym.com/'),
  ('workouts', 'trinity-boxing-club', 'Trinity Boxing Club', 'Boxing', 'A FiDi boxing club with group classes, bootcamp and private lessons for men, women and kids. You can book a trial group class first.', '20 Vesey St, New York, NY 10007', 'Financial District', 40.7117::float8, -74.0095::float8, 'J/Z from Bowery to Fulton St, then walk (~5 min)', '(212) 374-9393', 'https://www.trinityboxing.com/', 'Trial group class $30; memberships from $200/month', ARRAY['evening-hours']::text[], false, 'https://www.trinityboxing.com/pricing-1'),
  ('workouts', 'center-for-anti-violence-education', 'Center for Anti-Violence Education (CAE)', 'Self-defense', 'Founded in 1974 as Brooklyn Women''s Martial Arts, CAE runs empowerment self-defense workshops for women, girls, and LGBTQ and gender-nonconforming people. Its Self Defense 101 teaches basic blocks, strikes and de-escalation.', '30 Third Ave, Suite 104, Brooklyn, NY 11217', 'Boerum Hill', 40.6859::float8, -73.981::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, then walk (~5 min)', NULL::text, 'https://www.caeny.org/', 'Contact CAE for workshop dates and fees', ARRAY['women-focused','lgbtq-affirming','beginner-friendly']::text[], false, 'https://www.caeny.org/'),
  ('workouts', 'harlem-run', 'Harlem Run', 'Run club', 'A Harlem running collective started in 2013 that welcomes runners, walkers and joggers of all sizes, ages and abilities. Runs start on time and end together with a stretch.', NULL::text, 'Harlem', NULL::float8, NULL::float8, 'B/D from Grand St to 125 St', NULL::text, 'https://www.harlemrun.com/', 'Group runs Mon 7pm, Tue 6:30am, Wed 6pm; see site for meeting spots', ARRAY['beginner-friendly','outdoor','evening-hours']::text[], false, 'https://www.harlemrun.com/'),
  ('workouts', 'front-runners-new-york', 'Front Runners New York', 'Run club', 'NYC''s LGBTQ+ running club since 1979, which welcomes runners of all speeds and identities. Its social-paced Fun Runs in Central Park are open to everyone.', NULL::text, 'Central Park', NULL::float8, NULL::float8, 'B/D from Grand St to 59 St–Columbus Circle, then walk into Central Park', NULL::text, 'https://www.frny.org/', 'Fun Runs open to non-members (Central Park Wed 7pm & Sat 10am); membership available', ARRAY['lgbtq-affirming','beginner-friendly','outdoor','evening-hours']::text[], false, 'https://www.frny.org/activities'),
  ('workouts', 'north-brooklyn-runners', 'North Brooklyn Runners', 'Run club', 'A free community club with 20+ runs a week, including a Wednesday-night beginner run of 2–3 miles in McCarren Park where leaders bring up the rear so nobody gets left behind.', NULL::text, 'Williamsburg / Greenpoint (McCarren Park)', NULL::float8, NULL::float8, 'J/M from Essex St/Delancey St to Lorimer St, transfer to the G at Metropolitan Av to Nassau Av', NULL::text, 'https://www.northbrooklynrunners.org/', 'Free weekly runs', ARRAY['free','beginner-friendly','outdoor','evening-hours']::text[], true, 'https://www.northbrooklynrunners.org/nbr-schedule'),
  ('workouts', 'dashing-whippets-running-team', 'Dashing Whippets Running Team', 'Run club', 'A diverse NYC running team with 10+ weekly runs in Central Park, Lower Manhattan and Brooklyn, from casual easy runs to speed workouts in small pace groups.', NULL::text, 'Central Park / Lower Manhattan / Brooklyn', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.dashingwhippets.org/', 'Annual team membership; see site', ARRAY['outdoor','evening-hours']::text[], false, 'https://www.dashingwhippets.org/training/'),
  ('workouts', 'prospect-park-track-club', 'Prospect Park Track Club', 'Run club', 'A Brooklyn running club whose Wednesday 7pm social run from Grand Army Plaza welcomes all paces and ends at a nearby bar. A Friday-morning run also loops the Brooklyn Bridge Park piers.', NULL::text, 'Park Slope / Prospect Park', NULL::float8, NULL::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, transfer to the 2/3 to Grand Army Plaza', NULL::text, 'https://www.pptc.org/', 'Prospective members welcome on group runs; membership available', ARRAY['beginner-friendly','outdoor','evening-hours']::text[], false, 'https://www.pptc.org/group-runs'),
  ('workouts', 'broadway-dance-center', 'Broadway Dance Center', 'Dance', 'A Midtown studio with more than 350 drop-in classes a week in every style. Walk-ins are welcome, and Absolute Beginner workshops for ages 18+ need no prior experience.', '322 W 45th St, New York, NY 10036', 'Midtown West', 40.7598::float8, -73.9899::float8, 'B/D from Grand St to 42 St–Bryant Park, then walk west (~12 min)', '212-582-9304', 'https://www.broadwaydancecenter.com/', 'Pay per class; see site for rates', ARRAY['beginner-friendly','walk-in']::text[], false, 'https://www.broadwaydancecenter.com/'),
  ('workouts', 'steps-on-broadway', 'Steps on Broadway', 'Dance', 'An Upper West Side studio with daily adult and professional open classes in jazz, ballet, contemporary, tap and more, plus stretch-and-strengthen classes.', '2121 Broadway, New York, NY 10023', 'Upper West Side', 40.7807::float8, -73.9809::float8, 'B/D from Grand St to 59 St–Columbus Circle, transfer to the 1 to 72 St, then walk (~3 min)', '(212) 874-2410', 'https://www.stepsnyc.com/', 'Pay per class; see site for rates', ARRAY['beginner-friendly']::text[], false, 'https://www.stepsnyc.com/'),
  ('workouts', 'ailey-extension', 'Ailey Extension', 'Dance', 'Open dance and fitness classes at the Alvin Ailey building for every experience level, including Absolute Beginner sessions. Styles include Horton, hip hop, West African, Afro-Brazilian, Zumba and pilates.', '405 W 55th St, New York, NY 10019', 'Hell''s Kitchen', 40.7672::float8, -73.9853::float8, 'B/D from Grand St to 7 Av (53 St), then walk west (~8 min)', '212-405-9500', 'https://ailey.org/classes', '$26 per in-studio class; $15 online; class packages available', ARRAY['beginner-friendly','pilates','evening-hours']::text[], false, 'https://ailey.org/classes'),
  ('workouts', 'mark-morris-dance-center', 'Mark Morris Dance Center', 'Dance', 'A Fort Greene dance center offering adult drop-in classes with live music, plus a six-week intro series for people who are new to dance.', '3 Lafayette Ave, Brooklyn, NY 11217', 'Fort Greene', 40.6868::float8, -73.9774::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, then walk (~3 min)', '718-624-8400', 'https://www.markmorrisdancegroup.org/dance-center/adult-classes/', 'Pay per class; see site for rates', ARRAY['beginner-friendly']::text[], false, 'https://www.markmorrisdancegroup.org/dance-center/adult-classes/'),
  ('workouts', 'bike-new-york-free-adult-classes', 'Bike New York Free Adult Classes', 'Cycling', 'Free classes for adults, from Learn to Ride for total beginners to on-street riding skills, held at community bike education centers with loaner bikes and helmets. Nearby centers include Pier 76 in Hudson River Park and McCarren Park.', NULL::text, 'Citywide (Hudson River Park Pier 76, McCarren Park & more)', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.bike.nyc/education/classes/', 'Free (except Bike Maintenance for Beginners)', ARRAY['free','beginner-friendly','outdoor']::text[], true, 'https://www.bike.nyc/education/classes/'),
  ('workouts', 'asphalt-green-battery-park-city', 'Asphalt Green Battery Park City', 'Swimming', 'A downtown fitness center with a pool, adult swim classes from beginner up, and unlimited group and water-exercise classes with a full membership. It has a college student rate.', '212 North End Ave, New York, NY 10282', 'Battery Park City', 40.716::float8, -74.0153::float8, 'J/Z from Bowery to Chambers St, then walk west (~12 min)', '212-298-2900', 'https://www.asphaltgreen.org/', 'College student membership $100/mo (annual) or $110 month-to-month', ARRAY['student-friendly','beginner-friendly']::text[], false, 'https://www.asphaltgreen.org/membership/'),
  ('workouts', 'brooklyn-bridge-park-waterfront-workouts', 'Brooklyn Bridge Park Waterfront Workouts', 'Free classes', 'Free yoga, pilates and Zumba on the piers with Manhattan skyline views, open to all ages and abilities with no equipment needed. Classes run mainly May through September, and advance registration is encouraged.', NULL::text, 'Brooklyn Heights / DUMBO', NULL::float8, NULL::float8, 'F from Delancey St–Essex St to York St, then walk to the waterfront (~10 min)', NULL::text, 'https://brooklynbridgepark.org/events/waterfront-workouts/', 'Free; waiver required', ARRAY['free','outdoor','yoga','pilates','beginner-friendly']::text[], true, 'https://brooklynbridgepark.org/events/waterfront-workouts/'),
  ('doctors', 'nyee-eye-clinic-east-14th', 'New York Eye and Ear Infirmary of Mount Sinai – Eye Clinic', 'Dental & eye', 'Eye clinic on East 14th St that sees eye emergencies seven days a week. Overnight and after hours, eye emergencies are seen at the Mount Sinai Urgent Care on the ground floor of the same building.', '310 E 14th St, New York, NY 10003', 'East Village', 40.7323::float8, -73.9838::float8, '6 from Spring St to 14 St–Union Sq, L to 1 Av, walk 3 min.', '212-979-4000', 'https://www.nyee.edu', 'Most major insurance; call to confirm your plan.', ARRAY['24-7','evening-hours']::text[], false, 'https://www.nyee.edu/care/eye/after-hours-emergency'),
  ('clubs', 'bureau-of-general-services-queer-division', 'Bureau of General Services—Queer Division', 'Books & events', 'Manhattan''s queer bookstore, located inside the LGBT Community Center, with art exhibitions and regular in-person and virtual events. Open Tuesday through Sunday afternoons.', '208 W 13th St, Room 210, New York, NY 10011', 'West Village', 40.7379::float8, -74.001::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), 5 min walk', NULL::text, 'https://www.bgsqd.com', 'Free to browse; check site for event details', ARRAY['lgbtq-affirming']::text[], false, 'https://www.bgsqd.com/')
) AS v(cat, slug, name, kind, description, address, neighborhood, lat, lng, transit, phone, website, cost, tags, is_free, source_url)
JOIN categories c ON c.slug = v.cat
ON CONFLICT (slug) DO NOTHING;

