FROM (VALUES
  ('doctors', 'dermatology-specialists-greenwich-village', 'The Dermatology Specialists – Greenwich Village', 'Dermatology', 'Medical and cosmetic dermatology steps from Washington Square, treating acne, eczema, psoriasis, rosacea and hair loss and doing skin cancer screenings. Walk-ins are welcome, and it''s open 7 days with evening hours most weekdays.', '214 Sullivan St, New York, NY 10012', 'Greenwich Village', 40.7298::float8, -73.9989::float8, 'B/D from Grand St to W 4 St–Washington Sq, walk 3 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/greenwich-village/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/greenwich-village/'),
