  ('doctors', 'dermatology-specialists-south-street-seaport', 'The Dermatology Specialists – South Street Seaport', 'Dermatology', 'Downtown dermatology office treating acne, eczema, psoriasis, rosacea and warts, plus skin cancer screenings. Walk-ins are welcome on weekdays, with hours until 7pm on Wednesdays.', '220 Front St, New York, NY 10038', 'South Street Seaport', 40.7075::float8, -74.0018::float8, 'J/Z from Bowery to Fulton St, walk 6 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/south-street-seaport/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/south-street-seaport/'),
  ('doctors', 'dermatology-specialists-williamsburg', 'The Dermatology Specialists – Williamsburg', 'Dermatology', 'Williamsburg branch offering medical, surgical and cosmetic dermatology, including acne and eczema care and skin checks. Open 7 days with walk-ins welcome and hours until 6–7pm.', '152 Broadway, Brooklyn, NY 11211', 'Williamsburg', 40.7106::float8, -73.964::float8, 'J/Z from Bowery to Marcy Av, walk 5 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/williamsburg/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/williamsburg/'),
  ('doctors', 'dermatology-specialists-bushwick', 'The Dermatology Specialists – Bushwick', 'Dermatology', 'Neighborhood dermatology office right by the Myrtle Av station, for acne, eczema, rashes and skin checks. Walk-ins are welcome, and it''s open every day 9am–7pm.', '1163 Myrtle Ave, Brooklyn, NY 11206', 'Bushwick', 40.6973::float8, -73.9348::float8, 'J/Z from Bowery to Myrtle Av, walk 2 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/bushwick/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/bushwick/'),
  ('doctors', 'dermatology-specialists-downtown-brooklyn', 'The Dermatology Specialists – Downtown Brooklyn', 'Dermatology', 'Atlantic Avenue dermatology office for acne, eczema, psoriasis and skin cancer screenings, plus cosmetic treatments. Walk-ins are welcome, and it''s open daily until 7pm.', '440 Atlantic Ave, Brooklyn, NY 11217', 'Boerum Hill', 40.6862::float8, -73.9839::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, walk 8 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/downtown-brooklyn/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/downtown-brooklyn/'),
  ('doctors', 'dermatology-specialists-long-island-city', 'The Dermatology Specialists – Long Island City', 'Dermatology', 'LIC dermatology office near Vernon Blvd offering general and cosmetic dermatology, from acne and eczema care to skin checks. Open 7 days with walk-ins welcome and weekend hours until 7pm.', '10-41 47th Ave, Long Island City, NY 11101', 'Long Island City', 40.7448::float8, -73.9516::float8, '6 from Spring St to Grand Central–42 St, transfer to the 7 to Vernon Blvd–Jackson Av, walk 4 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/long-island-city/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/long-island-city/'),
  ('doctors', 'dermatology-specialists-astoria', 'The Dermatology Specialists – Astoria', 'Dermatology', 'Steinway Street dermatology office treating acne, eczema and hair loss and doing skin checks, plus cosmetic services. Walk-ins are welcome, and it''s open 7 days until 7pm.', '31-79 Steinway St, Astoria, NY 11103', 'Astoria', 40.758::float8, -73.92::float8, 'M (weekdays) from Delancey St–Essex St to Steinway St, walk 2 min.', '(212) 385-3700', 'https://www.thedermspecs.com/locations/astoria/', 'Most insurance accepted; the practice''s plan list includes UHC StudentResources, Fidelis Care, Healthfirst and MetroPlus. Call to confirm your plan.', ARRAY['walk-in','evening-hours','student-friendly']::text[], false, 'https://www.thedermspecs.com/locations/astoria/'),
  ('doctors', 'schweiger-dermatology-soho-crosby-street', 'Schweiger Dermatology Group – SoHo', 'Dermatology', 'SoHo office of a large dermatology group, treating acne, eczema and psoriasis and doing skin cancer screenings, with same-day and next-day appointments. Open until 7:30pm on Mondays, with early-morning slots on some days.', '132 Crosby St, 3rd Floor, New York, NY 10012', 'SoHo', 40.7247::float8, -73.9969::float8, 'B/D from Grand St to Broadway–Lafayette St, walk 3 min (or walk about 12 min).', '(212) 993-6131', 'https://www.schweigerderm.com/location/new-york/soho/', 'Accepts most major plans, including UnitedHealthcare, Aetna, Empire BCBS, Healthfirst, Cigna and Medicare. Call to confirm your plan.', ARRAY['evening-hours']::text[], false, 'https://www.schweigerderm.com/location/new-york/soho/'),
  ('doctors', 'schweiger-dermatology-spring-street-soho', 'Schweiger Dermatology Group – Spring Street SoHo', 'Dermatology', 'Dermatology office on Spring Street offering medical care for acne, eczema and psoriasis, skin cancer screenings and skin-of-color care. Open weekdays until 7pm and on Saturdays.', '75 Spring St, Floor 2, New York, NY 10012', 'SoHo / Nolita', 40.7225::float8, -73.9975::float8, 'Walk about 12 min west; it''s a 1-min walk from the Spring St (6) station.', '(646) 906-9614', 'https://www.schweigerderm.com/location/new-york/spring-street-soho/', 'Accepts most major plans, including UnitedHealthcare, Aetna, Empire BCBS, Healthfirst, Cigna and Medicare. Call to confirm your plan.', ARRAY['evening-hours']::text[], false, 'https://www.schweigerderm.com/location/new-york/spring-street-soho/'),
