  ('doctors', 'schweiger-dermatology-flatiron', 'Schweiger Dermatology Group – Flatiron', 'Dermatology', 'Flatiron dermatology office for acne, eczema and psoriasis, skin cancer screenings and skin-of-color care, with same-day appointments. Opens at 7am on weekdays and stays open until 7:30pm on Tuesdays and Wednesdays.', '21 W 19th St, New York, NY 10011', 'Flatiron', 40.7393::float8, -73.9927::float8, 'F from Delancey St–Essex St to 23 St, walk 5 min.', '(646) 665-3632', 'https://www.schweigerderm.com/location/new-york/flatiron/', 'Accepts most major plans, including UnitedHealthcare, Aetna, Empire BCBS, Healthfirst, Cigna and Medicare. Call to confirm your plan.', ARRAY['evening-hours']::text[], false, 'https://www.schweigerderm.com/location/new-york/flatiron/'),
  ('doctors', 'schweiger-dermatology-williamsburg', 'Schweiger Dermatology Group – Williamsburg', 'Dermatology', 'South Williamsburg office offering medical dermatology for acne, eczema and psoriasis and skin cancer screenings, plus allergy care. Open until 7:30pm on Mondays.', '217 Havemeyer St, 5th Floor, Brooklyn, NY 11211', 'Williamsburg', 40.7108::float8, -73.958::float8, 'J/Z from Bowery to Marcy Av, walk 3 min.', '(929) 277-3003', 'https://www.schweigerderm.com/location/new-york/williamsburg/', 'Accepts most major plans, including UnitedHealthcare, Aetna, Empire BCBS, Healthfirst, Cigna and Medicare. Call to confirm your plan.', ARRAY['evening-hours']::text[], false, 'https://www.schweigerderm.com/location/new-york/williamsburg/'),
  ('doctors', 'schweiger-dermatology-brooklyn-heights', 'Schweiger Dermatology Group – Brooklyn Heights', 'Dermatology', 'Court Street dermatology office for acne, eczema, psoriasis, skin cancer screenings and skin-of-color care, with same-day appointments. Open until 7pm on Mondays and Tuesdays and on some Saturdays.', '32 Court St, Suite 302, Brooklyn, NY 11201', 'Brooklyn Heights', 40.6935::float8, -73.9907::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, walk 7 min.', '(718) 408-4906', 'https://www.schweigerderm.com/location/new-york/brooklyn-heights/', 'Accepts most major plans, including UnitedHealthcare, Aetna, Empire BCBS, Healthfirst, Cigna and Medicare. Call to confirm your plan.', ARRAY['evening-hours']::text[], false, 'https://www.schweigerderm.com/location/new-york/brooklyn-heights/'),
  ('doctors', 'unionderm-union-square', 'UnionDerm – Union Square', 'Dermatology', 'Board-certified dermatologists on Union Square West who do skin cancer screenings and treat acne, rosacea, eczema and psoriasis, with a strong focus on laser and cosmetic treatments. Open Saturday mornings.', '19 Union Square W, 5th Floor, New York, NY 10003', 'Union Square', 40.7366::float8, -73.9906::float8, '6 from Spring St to 14 St–Union Sq, walk 3 min.', '(212) 366-5400', 'https://www.unionderm.com/unionderm-union-square/', 'Call to confirm your insurance. Cosmetic treatments are usually self-pay.', '{}'::text[], false, 'https://www.unionderm.com/directions-hours/'),
  ('doctors', 'nyu-langone-dermatologic-associates-41st-street', 'NYU Langone Dermatologic Associates', 'Dermatology', 'NYU Langone''s academic dermatology practice, treating everyday and complex skin, hair and nail conditions, including inflammatory skin disease, skin infections and skin cancer. A second office is at 240 E 38th St.', '222 E 41st St, 16th Floor, New York, NY 10017', 'Murray Hill / Midtown East', 40.7495::float8, -73.9735::float8, '6 from Spring St to Grand Central–42 St, walk 6 min.', '(212) 263-5015', 'https://nyulangone.org/locations/nyu-langone-dermatologic-associates', 'Most insurance accepted. Call to confirm your plan.', '{}'::text[], false, 'https://nyulangone.org/locations/nyu-langone-dermatologic-associates'),
  ('doctors', 'weill-cornell-dermatology-weill-greenberg-center', 'Weill Cornell Dermatology – Weill Greenberg Center', 'Dermatology', 'Main office of Weill Cornell''s Englander Department of Dermatology, offering general, complex medical and cosmetic dermatology. Home of the Center for Diverse Skin Complexions, which focuses on skin of color. Open Saturday mornings.', '1305 York Ave, 9th Floor, New York, NY 10021', 'Upper East Side', 40.766::float8, -73.9548::float8, '6 from Spring St to 68 St–Hunter College, walk 10 min.', '(646) 962-3376', 'https://weillcornell.org/dermatology-at-weill-greenberg-center', 'Most insurance accepted. Call to confirm your plan.', '{}'::text[], false, 'https://weillcornell.org/weill-cornell-dermatology-center-for-diverse-skin-complexions-cdsc'),
  ('doctors', 'weill-cornell-dermatology-brooklyn-heights', 'Weill Cornell Dermatology – Brooklyn Heights', 'Dermatology', 'Brooklyn Heights office of Weill Cornell''s full-service dermatology department, caring for skin, hair and nail conditions in patients of all ages.', '186 Joralemon St, Brooklyn, NY 11201', 'Brooklyn Heights', 40.6923::float8, -73.9914::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, walk 7 min.', '(646) 962-3376', 'https://weillcornell.org/services/dermatology', 'Most insurance accepted. Call to confirm your plan.', '{}'::text[], false, 'https://weillcornell.org/services/dermatology'),
  ('doctors', 'weill-cornell-dermatology-northwest-brooklyn-6th-ave', 'Weill Cornell Dermatology – Northwest Brooklyn (NYP Medical Group)', 'Dermatology', 'Brooklyn site of Weill Cornell dermatology and its Center for Diverse Skin Complexions, which treats acne, razor bumps, hyperpigmentation, melasma, keloids and hair loss in all skin tones.', '38 6th Ave, 4th Floor, Brooklyn, NY 11217', 'Prospect Heights', 40.6825::float8, -73.9755::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, walk 4 min.', '(646) 962-3376', 'https://weillcornell.org/weill-cornell-dermatology-center-for-diverse-skin-complexions-cdsc', 'Most insurance accepted. Call to confirm your plan.', '{}'::text[], false, 'https://weillcornell.org/weill-cornell-dermatology-center-for-diverse-skin-complexions-cdsc'),
  ('doctors', 'columbiadoctors-dermatology-midtown', 'ColumbiaDoctors Dermatology – Midtown', 'Dermatology', 'Columbia''s Midtown dermatology office near Rockefeller Center, treating acne, eczema, psoriasis and hair loss and offering yearly skin cancer screenings. Telehealth visits are also available.', '51 W 51st St, Suite 390, New York, NY 10019', 'Midtown', 40.7593::float8, -73.9781::float8, 'B/D from Grand St to 47–50 Sts–Rockefeller Ctr, walk 3 min.', '(212) 305-5293', 'https://www.columbiadoctors.org/locations/columbiadoctors-midtown/adult-services/dermatology', 'Most insurance accepted. Call to confirm your plan.', ARRAY['telehealth']::text[], false, 'https://www.columbiadoctors.org/specialties/dermatology/our-locations'),
  ('doctors', 'mount-sinai-dermatology-west-side-57th-street', 'Mount Sinai Dermatology – West Side', 'Dermatology', 'Newer Mount Sinai dermatology office on W 57th St, offering general dermatology for acute and chronic skin conditions, skin cancer diagnosis and cosmetic procedures.', '533 W 57th St, 6th Floor, Suite A, New York, NY 10019', 'Hell''s Kitchen / Clinton', 40.7703::float8, -73.9911::float8, 'B/D from Grand St to 59 St–Columbus Circle, walk 10 min.', '(212) 241-9728', 'https://www.mountsinai.org/locations/waldman-dermatology-west-side', 'Most insurance accepted. Call to confirm your plan.', '{}'::text[], false, 'https://www.mountsinai.org/care/dermatology/locations'),
  ('doctors', 'nyc-health-hospitals-metropolitan-dermatology', 'NYC Health + Hospitals/Metropolitan Dermatology', 'Dermatology', 'Public hospital dermatology clinic in East Harlem treating acne, eczema, psoriasis, rashes, hair loss and nail problems, and doing skin cancer screenings and biopsies.', '1901 First Ave, New York, NY 10029', 'East Harlem', 40.7845::float8, -73.9445::float8, '6 from Spring St to 96 St, walk 10 min.', '(844) 692-4692', 'https://www.nychealthandhospitals.org/metropolitan/services/dermatology/', 'Low-cost public care. Accepts Medicaid and most plans, and uninsured patients can apply for NYC Care or sliding-scale fees.', ARRAY['low-cost','sliding-scale','no-insurance-ok','medicaid']::text[], false, 'https://www.nychealthandhospitals.org/metropolitan/services/dermatology/'),
  ('doctors', 'nyc-health-hospitals-woodhull-dermatology', 'NYC Health + Hospitals/Woodhull Dermatology Clinic', 'Dermatology', 'Public hospital specialty dermatology clinic on the Williamsburg–Bushwick border. You need a referral from your doctor, and appointments are booked by phone on weekdays.', '760 Broadway, Brooklyn, NY 11206', 'Williamsburg / Bushwick', 40.6997::float8, -73.9417::float8, 'J from Bowery to Flushing Av, walk 2 min.', '(718) 388-5889', 'https://www.nychealthandhospitals.org/woodhull/', 'Low-cost public care. Accepts Medicaid and most plans, and uninsured patients can apply for NYC Care or sliding-scale fees. Referral required.', ARRAY['low-cost','sliding-scale','no-insurance-ok','medicaid']::text[], false, 'https://www.nychealthandhospitals.org/woodhull/make-an-appointment/'),
  ('doctors', 'gotham-health-broadway-dermatology', 'NYC Health + Hospitals/Gotham Health, Broadway Dermatology', 'Dermatology', 'Public community health center with a dermatology team that treats eczema, acne and psoriasis and does skin cancer screenings, for all New Yorkers regardless of insurance or immigration status. Open until 7pm on Mondays and Thursdays and on Saturdays.', '815 Broadway, Brooklyn, NY 11206', 'Williamsburg / Bushwick', 40.6985::float8, -73.9392::float8, 'J from Bowery to Flushing Av, walk 4 min.', '(844) 692-4692', 'https://www.nychealthandhospitals.org/locations/nyc-health-hospitals-gotham-health-broadway/', 'Low-cost public care, regardless of insurance or ability to pay. Accepts Medicaid, and sliding-scale fees and NYC Care are available.', ARRAY['low-cost','sliding-scale','no-insurance-ok','medicaid','evening-hours']::text[], false, 'https://www.nychealthandhospitals.org/gotham-health/our-services/dermatology-services/'),
  ('doctors', 'gotham-health-cumberland-dermatology', 'NYC Health + Hospitals/Gotham Health, Cumberland Dermatology', 'Dermatology', 'Fort Greene public health center offering dermatology for skin, hair and nail conditions such as acne and eczema, open to all New Yorkers regardless of insurance or immigration status.', '100 N Portland Ave, Brooklyn, NY 11205', 'Fort Greene', 40.6942::float8, -73.9768::float8, 'B from Grand St to DeKalb Av, walk 15 min (or take the B54 bus along Myrtle Ave).', '(844) 692-4692', 'https://www.nychealthandhospitals.org/locations/gotham-health-cumberland/', 'Low-cost public care, regardless of insurance or ability to pay. Accepts Medicaid, and sliding-scale fees and NYC Care are available.', ARRAY['low-cost','sliding-scale','no-insurance-ok','medicaid']::text[], false, 'https://www.nychealthandhospitals.org/gotham-health/our-services/dermatology-services/'),
  ('doctors', 'gotham-health-roosevelt-dermatology', 'NYC Health + Hospitals/Gotham Health, Roosevelt Dermatology', 'Dermatology', 'Jackson Heights public health center offering medical dermatology for acne, eczema and hair loss, plus some cosmetic procedures, open to all New Yorkers regardless of insurance or immigration status.', '37-50 72nd St, Jackson Heights, NY 11372', 'Jackson Heights', 40.748::float8, -73.8927::float8, 'F from Delancey St–Essex St to Jackson Hts–Roosevelt Av, walk 2 min.', '(844) 692-4692', 'https://www.nychealthandhospitals.org/locations/nyc-health-hospitals-gotham-health-roosevelt/', 'Low-cost public care, regardless of insurance or ability to pay. Accepts Medicaid, and sliding-scale fees and NYC Care are available.', ARRAY['low-cost','sliding-scale','no-insurance-ok','medicaid']::text[], false, 'https://www.nychealthandhospitals.org/gotham-health/our-services/dermatology-services/')
