ON CONFLICT (slug) DO NOTHING;

-- ───────────── Nearby New Jersey: Jersey City & Hoboken via PATH (Oct 2026) ─────────────
INSERT INTO listings
  (category_id, slug, name, kind, description, address, neighborhood, lat, lng, transit, phone, website, cost, tags, is_free, source_url)
SELECT c.id, v.slug, v.name, v.kind, v.description, v.address, v.neighborhood, v.lat, v.lng,
       v.transit, v.phone, v.website, v.cost, v.tags, v.is_free, v.source_url
FROM (VALUES
  ('doctors', 'alliance-community-healthcare-jersey-city', 'Alliance Community Healthcare', 'Primary care', 'Federally qualified health center offering primary care, OB/GYN and family planning, STI testing, transgender care, dental and behavioral health. Sliding-scale fees and no one is turned away for inability to pay; walk-ins welcome during clinic hours.', '115 Christopher Columbus Dr, Jersey City, NJ 07302', 'Downtown Jersey City', 40.7169::float8, -74.0336::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; walk about 8 min to Christopher Columbus Dr.', '(201) 451-6300', 'https://alliancech.org', 'Sliding scale; accepts NJ FamilyCare/Medicaid, Medicare and most insurance; uninsured welcome', ARRAY['sliding-scale','low-cost','no-insurance-ok','medicaid','walk-in','lgbtq-affirming','spanish']::text[], false, 'https://alliancech.org/locations'),
  ('doctors', 'north-hudson-community-action-health-center-jersey-city', 'North Hudson Community Action Corp. Health Center – Jersey City', 'Primary care', 'Community health center in the Heights offering adult medicine, women''s health services and dental care. Uninsured patients can use an income-based sliding fee scale.', '324 Palisade Ave, Jersey City, NJ 07307', 'The Heights, Jersey City', 40.74::float8, -74.0467::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and take the station elevator up to the Heights; about a 5-min walk.', '(201) 210-0200', 'https://nhcac.org', 'Sliding fee scale; accepts NJ FamilyCare/Medicaid and self-pay', ARRAY['sliding-scale','low-cost','no-insurance-ok','medicaid','evening-hours']::text[], false, 'https://nhcac.org/about/sites-locations/'),
  ('doctors', 'hoboken-family-planning', 'Hoboken Family Planning', 'Sexual & reproductive health', 'Nonprofit family planning clinic offering birth control, STI testing and treatment, pregnancy testing, cervical cancer screening and counseling. Serves uninsured, underinsured, Medicaid and insured patients; call to book.', '124 Grand St, Hoboken, NJ 07030', 'Downtown Hoboken', 40.7388::float8, -74.0364::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 12 min west to Grand St.', '(201) 963-0300', 'https://www.hobfamplan.org', 'Sliding scale based on income; Medicaid and insurance accepted', ARRAY['sliding-scale','low-cost','no-insurance-ok','medicaid','women-focused','confidential','evening-hours','spanish']::text[], false, 'https://www.hobfamplan.org/'),
  ('doctors', 'jcmc-womens-health-grove-street-jersey-city', 'Jersey City Medical Center Women''s Health at Grove Street', 'Sexual & reproductive health', 'RWJBarnabas Health OB/GYN center right on the Grove Street PATH plaza, offering annual exams, gynecology, prenatal and midwifery care, menopause care, mammography and ultrasound. Telemedicine visits are also offered.', '116 Newark Ave, Jersey City, NJ 07302', 'Downtown Jersey City (Grove St)', 40.72::float8, -74.0426::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; the center is on the PATH plaza.', '(201) 984-1270', 'https://rwjbh.org/our-locations/specialty-centers/jersey-city-medical-center-womens-health-at-grov', 'Insurance-based; call about coverage', ARRAY['women-focused','telehealth']::text[], false, 'https://rwjbh.org/our-locations/specialty-centers/jersey-city-medical-center-womens-health-at-grov'),
  ('doctors', 'jersey-city-medical-center-emergency-department', 'Jersey City Medical Center Emergency Department', 'Urgent & emergency', '24/7 emergency department at RWJBarnabas Health''s Jersey City Medical Center, a Level II trauma center. For emergencies call 911.', '355 Grand St, Jersey City, NJ 07302', 'Downtown Jersey City', 40.7153::float8, -74.0508::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; walk about 15 min south via Jersey Ave.', '(201) 915-2000', 'https://www.rwjbh.org/jersey-city-medical-center/', 'Insurance billed; emergency care is given regardless of ability to pay', ARRAY['24-7','walk-in']::text[], false, 'https://www.rwjbh.org/jersey-city-medical-center/patients-visitors/phone-directory/'),
  ('doctors', 'hoboken-university-hospital-emergency', 'Hoboken University Hospital Emergency Room', 'Urgent & emergency', '24/7 emergency room at Hoboken University Hospital (formerly Hoboken University Medical Center), now part of Hudson Regional Health. For emergencies call 911.', '308 Willow Ave, Hoboken, NJ 07030', 'Hoboken', 40.7415::float8, -74.034::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 15 min to Willow Ave & 4th St.', '(201) 418-1000', 'https://www.hudsonregionalhospital.com/', 'Insurance billed; emergency care is given regardless of ability to pay', ARRAY['24-7','walk-in']::text[], false, 'https://www.hudsonregionalhospital.com/?p=10'),
  ('doctors', 'citymd-urgent-care-hoboken', 'CityMD Hoboken Urgent Care', 'Urgent & emergency', 'Walk-in urgent care for colds, UTIs, minor injuries and more, open seven days. Accepts insurance and self-pay.', '231 Washington St, Hoboken, NJ 07030', 'Hoboken', 40.7396::float8, -74.0299::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 8 min up Washington St.', '(201) 754-1006', 'https://www.citymd.com/urgent-care-locations/nj/hoboken', 'Insurance or self-pay', ARRAY['walk-in','evening-hours']::text[], false, 'https://www.citymd.com/urgent-care-locations/nj/hoboken'),
  ('doctors', 'citymd-urgent-care-grove-street-jersey-city', 'CityMD Jersey City – Grove Street Urgent Care', 'Urgent & emergency', 'Walk-in urgent care a block from the Grove Street PATH, open weekdays until 8pm and on weekends. Accepts insurance and self-pay.', '340 Grove St, Jersey City, NJ 07302', 'Downtown Jersey City (Grove St)', 40.7205::float8, -74.0427::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; walk 2 min to Grove & Morgan Sts.', '(201) 354-1957', 'https://www.citymd.com/urgent-care-locations/nj/jersey-city-grove-street', 'Insurance or self-pay', ARRAY['walk-in','evening-hours']::text[], false, 'https://www.citymd.com/urgent-care-locations/nj/jersey-city-grove-street'),
  ('doctors', 'citymd-urgent-care-journal-square-jersey-city', 'CityMD Jersey City – Journal Square Urgent Care', 'Urgent & emergency', 'Walk-in urgent care near the Journal Square PATH, open weekdays until 8pm and on weekends. Accepts insurance and self-pay.', '32 Journal Square Plaza, Jersey City, NJ 07306', 'Journal Square, Jersey City', 40.7327::float8, -74.0625::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; short walk from the station.', '(201) 354-1955', 'https://www.citymd.com/urgent-care-locations/nj/jersey-city-journal-square', 'Insurance or self-pay', ARRAY['walk-in','evening-hours']::text[], false, 'https://www.citymd.com/urgent-care-locations/nj/jersey-city-journal-square'),
  ('doctors', 'stevens-student-health-services-hoboken', 'Stevens Student Health Services', 'Student health', 'Acute care clinic for enrolled Stevens Institute of Technology students, including STI testing by appointment. Located in the Student Wellness Center next to North Hall; 24-hour virtual care is available when the office is closed.', 'Student Wellness Center, 1 Castle Point Terrace, Hoboken, NJ 07030', 'Hoboken (Stevens campus)', 40.7448::float8, -74.0252::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 20 min up Washington or Hudson St to campus, or take NJ Transit bus 126 up Washington St.', '(201) 216-5678', 'https://www.stevens.edu/student-health-services', 'For enrolled Stevens students', ARRAY['student-friendly','confidential']::text[], false, 'https://www.stevens.edu/directory/student-health-services'),
  ('doctors', 'saint-peters-university-health-services-jersey-city', 'Saint Peter''s University Health Services', 'Student health', 'Nurse-directed campus health office for enrolled Saint Peter''s University students, offering first aid, acute illness care, health assessments and referrals, with a physician assistant one day a week.', 'Saint Peter Hall, 1st Floor, 2641 John F. Kennedy Blvd, Jersey City, NJ 07306', 'Journal Square / McGinley Square, Jersey City', 40.727::float8, -74.0716::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; then about a 15-min walk south or a short bus ride down Kennedy Blvd.', '(201) 761-7445', 'https://www.saintpeters.edu/health-services/', 'For enrolled Saint Peter''s students', ARRAY['student-friendly','confidential']::text[], false, 'https://www.saintpeters.edu/health-services/'),
  ('doctors', 'jersey-city-family-health-center-dental-eye', 'Jersey City Family Health Center (Dental & Eye Care)', 'Dental & eye', 'Jersey City Medical Center outpatient center near Journal Square offering general dentistry, oral surgery and ophthalmology (eye) care, plus family health services. Call to ask about coverage and appointments.', '418 Summit Ave, Jersey City, NJ 07306', 'Journal Square, Jersey City', 40.7297::float8, -74.0614::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; walk about 7 min south on Summit Ave.', '(201) 499-1969', 'https://rwjbh.org/our-locations/specialty-centers/the-jersey-city-family-health-center', 'Call about insurance and fees', '{}'::text[], false, 'https://rwjbh.org/our-locations/specialty-centers/the-jersey-city-family-health-center'),
  ('mental-health', 'stevens-caps-counseling-hoboken', 'Stevens Counseling & Psychological Services (CAPS)', 'Therapy', 'Free counseling for enrolled Stevens students, with a licensed clinician reachable 24/7 by phone for crises. Free unlimited teletherapy is also offered through Uwill.', 'Student Wellness Center, 2nd Floor, 1 Castle Point Terrace, Hoboken, NJ 07030', 'Hoboken (Stevens campus)', 40.7448::float8, -74.0252::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 20 min up Washington or Hudson St to campus, or take NJ Transit bus 126 up Washington St.', '(201) 216-5177', 'https://www.stevens.edu/counseling-psychological-services', 'Free for enrolled Stevens students', ARRAY['free','student-friendly','confidential','telehealth','24-7']::text[], true, 'https://www.stevens.edu/directory/counseling-and-psychological-services'),
  ('mental-health', 'saint-peters-university-caps-jersey-city', 'Saint Peter''s University Counseling & Psychological Services', 'Therapy', 'Free, confidential counseling for currently enrolled Saint Peter''s University students, plus workshops, groups and teletherapy through Uwill.', 'Saint Peter Hall, 2nd Floor, 2641 John F. Kennedy Blvd, Jersey City, NJ 07306', 'Journal Square / McGinley Square, Jersey City', 40.727::float8, -74.0716::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; then about a 15-min walk south or a short bus ride down Kennedy Blvd.', '(201) 761-6420', 'https://www.saintpeters.edu/caps/counseling-services/', 'Free for enrolled Saint Peter''s students', ARRAY['free','student-friendly','confidential','telehealth']::text[], true, 'https://www.saintpeters.edu/caps/counseling-services/'),
  ('mental-health', 'hccc-mental-health-counseling-jersey-city', 'HCCC Mental Health Counseling & Wellness Center', 'Therapy', 'Free, confidential short-term counseling (in person or remote, walk-in or scheduled) for registered Hudson County Community College students at the Journal Square campus.', '70 Sip Ave, 3rd Floor, Jersey City, NJ 07306', 'Journal Square, Jersey City', 40.7308::float8, -74.0624::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; walk about 3 min.', '(201) 360-4229', 'https://www.hccc.edu/student-success/personal-support/mental-health-counseling-wellness-center/', 'Free for registered HCCC students', ARRAY['free','student-friendly','confidential','walk-in','telehealth']::text[], true, 'https://www.hccc.edu/student-success/personal-support/mental-health-counseling-wellness-center/'),
  ('mental-health', 'hoboken-community-mental-health-clinic', 'Hoboken Community Mental Health Clinic', 'Therapy', 'Hudson Regional Health outpatient clinic offering therapy, psychiatric evaluation and medication management for anxiety, depression, trauma, ADHD and more. Accepts Medicaid, Medicare and most major insurance.', '122 Clinton St, Hoboken, NJ 07030', 'Downtown Hoboken', 40.7387::float8, -74.0354::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 12 min west to Clinton St.', '(201) 792-8200', 'https://www.hudsonregionalhospital.com/?p=48263', 'Medicaid, Medicare and most insurance accepted', ARRAY['medicaid','evening-hours']::text[], false, 'https://www.hudsonregionalhospital.com/?p=48263'),
  ('mental-health', 'jcmc-behavioral-health-jersey-city', 'Jersey City Medical Center Outpatient Behavioral Health', 'Therapy', 'Outpatient individual, group, couples and family therapy, psychological testing and medication management through RWJBarnabas Health''s Jersey City Medical Center. No patient is denied service due to inability to pay; Medicaid and most insurance accepted.', '355 Grand St, Jersey City, NJ 07302', 'Downtown Jersey City', 40.7153::float8, -74.0508::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; walk about 15 min south via Jersey Ave.', '(201) 915-2100', 'https://www.rwjbh.org/jersey-city-medical-center/treatment-care/mental-health-behavioral-health/', 'Medicaid, Medicare and most insurance; no one denied for inability to pay', ARRAY['medicaid','no-insurance-ok']::text[], false, 'https://www.rwjbh.org/jersey-city-medical-center/treatment-care/mental-health-behavioral-health/'),
  ('mental-health', 'jcmc-psychiatric-emergency-screening-jersey-city', 'Jersey City Medical Center Psychiatric Emergency Screening Service', 'Crisis & drop-in center', 'Hudson County''s designated 24/7 psychiatric emergency screening center, providing crisis assessment and stabilization for adults and young people at Jersey City Medical Center. In an emergency call 911 or 988.', '355 Grand St, Jersey City, NJ 07302', 'Downtown Jersey City', 40.7153::float8, -74.0508::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; walk about 15 min south via Jersey Ave.', '(866) 367-6023', 'https://www.rwjbh.org/treatment-care/mental-health-and-behavioral-health/conditions/psychiatric-emergency-screening-service/', 'Emergency care regardless of ability to pay', ARRAY['24-7','walk-in']::text[], false, 'https://www.rwjbh.org/treatment-care/mental-health-and-behavioral-health/conditions/psychiatric-emergency-screening-service/'),
  ('mental-health', '2ndfloor-youth-helpline-nj', '2NDFLOOR Youth Helpline (New Jersey)', 'Crisis line', 'Free, anonymous and confidential call-or-text helpline for New Jersey youth and young adults, open 24/7 to talk about anything from dating and school to mental health and LGBTQIA+ questions.', NULL::text, 'New Jersey — phone / online', NULL::float8, NULL::float8, NULL::text, '(888) 222-2228', 'https://www.2ndfloor.org/', 'Free', ARRAY['free','confidential','24-7','lgbtq-affirming','student-friendly']::text[], true, 'https://www.2ndfloor.org/'),
  ('mental-health', 'nj-mentalhealthcares-helpline', 'NJ MentalHealthCares Helpline', 'Crisis line', 'State-funded helpline offering free, confidential emotional support and referrals to mental health, housing, legal and other services in New Jersey, weekdays 8am–8pm. For a crisis, call or text 988.', NULL::text, 'New Jersey — phone / online', NULL::float8, NULL::float8, NULL::text, '(866) 202-4357', 'https://www.njmentalhealthcares.org/', 'Free', ARRAY['free','confidential','evening-hours']::text[], true, 'https://www.nj.gov/humanservices/dmhas/documents/pdf/miscl/DMHAS-Hotline-helplines-April-2026.pdf'),
  ('mental-health', 'nami-hudson-county-support-groups', 'NAMI Hudson County Support Groups', 'Support group', 'Free, peer-led monthly support groups: Connections groups for adults living with a mental health condition and Family groups for loved ones. Virtual groups meet on Zoom on the third Tuesday of each month.', NULL::text, 'New Jersey — phone / online', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.namihudsoncounty.org/', 'Free', ARRAY['free','telehealth','evening-hours']::text[], true, 'https://www.namihudsoncounty.org/'),
  ('mental-health', 'hudson-pride-center-jersey-city', 'Hudson Pride Center', 'Support group', 'New Jersey''s largest LGBTQ+ social services center, offering free support groups, community programs and health and mental health support near Journal Square.', '3000 John F. Kennedy Blvd, Suite 306, Jersey City, NJ 07306', 'Journal Square, Jersey City', 40.7359::float8, -74.0628::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; walk about 5 min north on Kennedy Blvd.', '(201) 963-4779', 'https://www.hudsonpride.org/', 'Free', ARRAY['free','lgbtq-affirming']::text[], true, 'https://www.hudsonpride.org/contact'),
  ('resources', 'jersey-city-free-public-library-main', 'Priscilla Gardner Main Library (Jersey City Free Public Library)', 'Library', 'Jersey City''s main public library downtown, with study space, computers, a children''s room and the New Jersey Room local-history collection. Open Monday–Saturday, until 8pm Monday–Thursday.', '472 Jersey Ave, Jersey City, NJ 07302', 'Downtown Jersey City', 40.7189::float8, -74.0474::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Grove St, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Grove St; walk about 8 min to Jersey Ave & Montgomery St.', '(201) 547-4526', 'https://jclibrary.org/', 'Free', ARRAY['free','evening-hours']::text[], true, 'https://jclibrary.org/branch/priscilla-gardner-main-library-departments/'),
  ('resources', 'jersey-city-library-pavonia-branch', 'Pavonia Branch Library (Jersey City Free Public Library)', 'Library', 'Neighborhood branch of the Jersey City Free Public Library near Hamilton Park and Newport, open until 8pm on Mondays.', '326 8th St, Jersey City, NJ 07302', 'Hamilton Park / Harsimus, Jersey City', 40.7273::float8, -74.0479::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Newport; walk about 12 min west to 8th St.', '(201) 547-4808', 'https://jclibrary.org/branch/pavonia-branch/', 'Free', ARRAY['free']::text[], true, 'https://jclibrary.org/branch/pavonia-branch/'),
  ('resources', 'jersey-city-library-heights-branch', 'Heights Branch Library (Jersey City Free Public Library)', 'Library', 'Jersey City Heights branch library, reopened in 2026 after major upgrades; open until 8pm on Thursdays.', '14 Zabriskie St, Jersey City, NJ 07307', 'The Heights, Jersey City', 40.7457::float8, -74.0504::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and take the station elevator up to the Heights; about a 10-min walk.', '(201) 547-4556', 'https://jclibrary.org/branch/heights-branch/', 'Free', ARRAY['free']::text[], true, 'https://jclibrary.org/branch/heights-branch/'),
  ('resources', 'hoboken-public-library', 'Hoboken Public Library', 'Library', 'Hoboken''s main public library, with study space, computers and free events; open evenings until 8pm on Mondays.', '500 Park Ave, Hoboken, NJ 07030', 'Hoboken', 40.7429::float8, -74.0323::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; walk about 15 min to Park Ave & 5th St.', '(201) 420-2346', 'https://www.hobokenlibrary.org/', 'Free', ARRAY['free','evening-hours']::text[], true, 'https://www.hobokenlibrary.org/'),
  ('resources', 'womenrising-jersey-city', 'WomenRising', 'Safety', 'Hudson County nonprofit providing domestic violence services including a 24/7 hotline, emergency shelter, counseling, support groups, safety planning and help with restraining orders and court, in English and Spanish. Walk-ins weekdays 9am–5pm.', '270 Fairmount Ave, Jersey City, NJ 07306', 'Journal Square / McGinley Square, Jersey City', 40.7238::float8, -74.0691::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; then about a 15-min walk south.', '(201) 333-5700', 'https://www.womenrising.org/', 'Free', ARRAY['free','24-7','women-focused','confidential','spanish','walk-in']::text[], true, 'https://www.womenrising.org/domestic-violence'),
  ('resources', 'hudson-speaks-sexual-violence-helpline', 'Hudson SPEAKS Sexual Violence Helpline', 'Safety', 'Hudson County''s sexual violence program, listed by the NJ Coalition Against Sexual Assault, with a free, confidential 24-hour helpline staffed by trained advocates for survivors and their loved ones.', NULL::text, 'New Jersey — phone / online', NULL::float8, NULL::float8, NULL::text, '(201) 795-5757', 'https://njcasa.org/find-help/', 'Free', ARRAY['free','24-7','confidential']::text[], true, 'https://njcasa.org/find-help/'),
  ('resources', 'northeast-new-jersey-legal-services-jersey-city', 'Northeast New Jersey Legal Services – Hudson County Office', 'Legal help', 'Free civil legal help for eligible low-income Hudson, Bergen and Passaic County residents with housing, family, consumer, public benefits and immigration problems.', '574 Summit Ave, 2nd Floor, Jersey City, NJ 07306', 'Journal Square, Jersey City', 40.7337::float8, -74.0591::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; walk about 7 min east to Summit Ave.', '(201) 792-6363', 'https://lsnj.org/nnjls/', 'Free for eligible low-income residents', ARRAY['free']::text[], true, 'https://lsnj.org/nnjls/'),
  ('resources', 'hoboken-community-center-food-pantry', 'Hoboken Community Center Food Pantry', 'Food', 'Free pre-bagged groceries with fresh produce and bread every two weeks, plus a monthly personal care pantry with toiletries and menstrual products, for community members facing food insecurity. Check the online calendar for dates.', '1301 Washington St, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7524::float8, -74.0262::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH from 14th St to Hoboken; then NJ Transit bus 126 up Washington St, or about a 30-min walk.', NULL::text, 'https://hobokencc.org/pantry', 'Free', ARRAY['free']::text[], true, 'https://hobokencc.org/pantry'),
  ('resources', 'hccc-food-pantry-jersey-city', 'HCCC Food Pantry (Journal Square Campus)', 'Food', 'Free canned goods, snacks, drinks and frozen meals for currently enrolled Hudson County Community College students and staff; no appointment needed, just bring your student ID.', '2 Enos Pl, Lower Level, Room J002, Jersey City, NJ 07306', 'Journal Square, Jersey City', 40.7296::float8, -74.0637::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), then PATH (JSQ–33rd St line) to Journal Square, or J/Z from Bowery to Chambers St, walk to World Trade Center PATH and ride to Journal Square; walk about 5 min.', '(201) 360-4109', 'https://www.hccc.edu/student-success/personal-support/hudsonhelps/food-pantry.html', 'Free for enrolled HCCC students and staff', ARRAY['free','student-friendly','walk-in']::text[], true, 'https://www.hccc.edu/student-success/personal-support/hudsonhelps/food-pantry.html'),
  ('resources', 'nj-familycare', 'NJ FamilyCare', 'Health coverage', 'New Jersey''s free or low-cost public health insurance (Medicaid and CHIP) for qualified NJ residents of any age. Apply online or by phone; NJ residents only.', NULL::text, 'New Jersey — phone / online', NULL::float8, NULL::float8, NULL::text, '(800) 701-0710', 'https://njfamilycare.dhs.state.nj.us/', 'Free or low-cost for eligible NJ residents', ARRAY['free','low-cost','medicaid']::text[], true, 'https://njfamilycare.dhs.state.nj.us/'),
  ('resources', 'get-covered-new-jersey', 'Get Covered New Jersey', 'Health coverage', 'New Jersey''s official health insurance marketplace, where most enrollees qualify for financial help and free trained assisters can help you enroll. Open enrollment runs November 1–January 31; NJ residents only.', NULL::text, 'New Jersey — phone / online', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://nj.gov/getcoverednj/', 'Free to apply; financial help available', ARRAY['low-cost']::text[], false, 'https://nj.gov/getcoverednj/'),
  ('workouts', 'hoboken-cove-community-boathouse-hoboken', 'Hoboken Cove Community Boathouse', 'Paddling', 'All-volunteer nonprofit that calls itself New Jersey''s largest free paddling program, with free kayaking, stand-up paddleboarding and outrigger canoeing in the protected cove at Maxwell Place Park. Free paddle days run roughly late May through September; check the schedule before going.', 'Maxwell Place Park, Frank Sinatra Dr & Maxwell Pl, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7492::float8, -74.0237::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~20 min north along the waterfront.', NULL::text, 'https://www.hobokencoveboathouse.org/', 'Free (seasonal free paddle days)', ARRAY['free','outdoor','beginner-friendly']::text[], true, 'https://sites.google.com/hobokencoveboathouse.org/hccb/home'),
  ('workouts', 'gravity-vault-hoboken', 'The Gravity Vault — Hoboken', 'Climbing', 'Indoor rock climbing gym with day and punch passes, plus Introduction to Climbing classes and staff belays for first-timers. Its multipurpose rooms host yoga classes, and it''s open until 10 pm on weekdays.', '1423 Clinton St, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7549::float8, -74.0301::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and walk ~12 min (or walk ~25 min from Hoboken Terminal).', '(201) 740-1423', 'https://gravityvault.com/locations/hoboken-nj', 'Day passes and punch passes; intro classes available (see site for prices)', ARRAY['beginner-friendly','evening-hours','yoga']::text[], false, 'https://gravityvault.com/locations/hoboken-nj'),
  ('workouts', 'fleet-feet-fun-run-hoboken', 'Fleet Feet Hoboken Tuesday Fun Run', 'Run club', 'Free weekly fun run from the locally owned Fleet Feet running store, every Tuesday at 7 pm. The roughly 3-mile route loops around Hoboken with multiple pace groups, including a social pace group.', '604 Washington St, Hoboken, NJ 07030', 'Midtown Hoboken', 40.7437::float8, -74.0293::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~15 min up Washington St.', NULL::text, 'https://www.fleetfeet.com/s/hoboken/', 'Free', ARRAY['free','beginner-friendly','evening-hours','outdoor']::text[], true, 'https://www.fleetfeet.com/s/hoboken/'),
  ('workouts', 'jersey-city-runners-club', 'Jersey City Runners', 'Run club', 'Grassroots running group founded in 2008, now a Road Runners Club of America–affiliated nonprofit with thousands of Meetup members. It posts group runs almost daily, including waterfront runs and speedwork at the Lincoln Park track.', NULL::text, 'Jersey City (various meeting spots, incl. waterfront and Lincoln Park)', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.meetup.com/jcrunners/', 'See Meetup for membership details', ARRAY['outdoor']::text[], false, 'https://www.meetup.com/jcrunners/'),
  ('workouts', 'liberty-state-park-jersey-city', 'Liberty State Park', 'Outdoor fitness', 'Large state park on the Hudson with no entrance fee, open daily 6 am–10 pm. The two-mile Hudson River Waterfront Walkway (Liberty Walk) is a flat, scenic route for running, walking and biking with Statue of Liberty and skyline views.', '1 Audrey Zapp Dr, Jersey City, NJ 07305', 'Liberty State Park, Jersey City', 40.7072::float8, -74.0352::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Exchange Place, then walk ~25 min south via Paulus Hook and the waterfront walkway to the CRRNJ Terminal.', '(201) 915-3400', 'https://dep.nj.gov/parksandforests/state-park/liberty-state-park/', 'Free', ARRAY['free','outdoor']::text[], true, 'https://dep.nj.gov/parksandforests/state-park/liberty-state-park/'),
  ('workouts', 'pershing-field-pool-jersey-city', 'Pershing Field Pool', 'Swimming', 'City-run indoor 25-meter, six-lane pool with a retractable glass roof inside Pershing Field Park in the Heights. Open seven days a week year-round to residents and non-residents; schedules and fees are on JC Rec''s RecDesk.', 'Pershing Field Park, Central Ave, Jersey City, NJ 07307', 'The Heights, Jersey City', 40.7423::float8, -74.0535::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, Hudson-Bergen Light Rail to 9th St–Congress St, take the elevator up to the Heights and walk ~18 min.', NULL::text, 'https://jcrec.recdesk.com/', 'See JC Rec RecDesk for current fees', '{}'::text[], false, 'https://jerseycitynj.gov/news/mayor_unveils_retractable_roof_on_pershing_pool'),
  ('workouts', 'fitness-in-the-park-hoboken', 'Hoboken Fitness in the Park', 'Free classes', 'The City of Hoboken''s free summer series of outdoor classes led by local studios, from yoga and Pilates to HIIT. The 2026 season ran June 8–Aug 26 at parks including Pier A, Southwest and ResilienCity Park; bring a mat, sneakers and water.', NULL::text, 'Hoboken parks (Pier A Park, Southwest Park, ResilienCity Park)', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://www.hobokennj.gov/news/city-of-hoboken-announces-return-of-free-summer-fun-programming-starting-june-2', 'Free (summer only)', ARRAY['free','outdoor','yoga','pilates']::text[], true, 'https://www.hobokennj.gov/news/city-of-hoboken-announces-return-of-free-summer-fun-programming-starting-june-2'),
  ('workouts', 'cyclebar-hoboken', 'CycleBar — Hoboken', 'Cycling', 'Indoor cycling studio in the Monroe Center for all fitness levels. New riders can take a first class for $15 or get 3 rides for $79.', '720 Monroe St, Suite C301, Hoboken, NJ 07030', 'Northwest Hoboken', 40.7475::float8, -74.0378::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and walk ~5 min.', '(973) 320-3180', 'https://www.cyclebar.com/location/hoboken', 'First class $15; 3 rides for $79 (intro)', ARRAY['beginner-friendly']::text[], false, 'https://www.cyclebar.com/location/hoboken'),
  ('workouts', 'cyclebar-jersey-city', 'CycleBar — Jersey City', 'Cycling', 'Indoor cycling studio in downtown Jersey City with rides for all fitness and experience levels, from 30-minute Xpress classes to strength-focused sessions. First ride is $15 for new riders.', '65 Bay St, Jersey City, NJ 07302', 'Downtown Jersey City (Harsimus)', 40.7203::float8, -74.0376::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St (or F/M to 14 St and PATH to Newport); walk ~7 min.', '(201) 375-4775', 'https://www.cyclebar.com/location/jersey-city', 'First ride $15', ARRAY['beginner-friendly']::text[], false, 'https://www.cyclebar.com/location/jersey-city'),
  ('workouts', 'nimbus-arts-center-adult-dance-jersey-city', 'School of Nimbus — NimbusFIT Adult Dance & Fitness', 'Dance', 'The school of Nimbus Dance, a professional company based at Nimbus Arts Center, runs NimbusFIT adult dance and fitness classes at its downtown Jersey City campus. Check the NimbusFIT page for current styles and schedule.', '329 Warren St, Jersey City, NJ 07302', 'Downtown Jersey City (Powerhouse Arts District)', 40.72::float8, -74.0384::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~6 min.', '(201) 377-0718', 'https://www.schoolofnimbus.org/', 'Contact for class pricing', '{}'::text[], false, 'https://www.schoolofnimbus.org/'),
  ('workouts', 'rumble-boxing-hoboken', 'Rumble Boxing — Hoboken', 'Boxing', 'Boxing-inspired group fitness studio with 10-round heavy-bag classes — no experience necessary. Offers drop-ins plus 4-class, 8-class and unlimited monthly memberships.', '1202 Shipyard Ln, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7523::float8, -74.0246::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~25 min north (or Hudson-Bergen Light Rail to 9th St–Congress St and walk ~15 min).', '(201) 523-6175', 'https://www.rumbleboxinggym.com/location/hoboken', 'Drop-in and monthly memberships (contact studio for prices)', ARRAY['beginner-friendly']::text[], false, 'https://www.rumbleboxinggym.com/location/hoboken'),
  ('workouts', 'cko-kickboxing-jersey-city', 'CKO Kickboxing — Jersey City', 'Boxing', 'Cardio kickboxing gym on real heavy bags in the Powerhouse Arts District. CKO says a first class is free for new guests (participation can vary by studio).', '150 Bay St, Jersey City, NJ 07302', 'Downtown Jersey City (Powerhouse Arts District)', 40.7211::float8, -74.0399::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~5 min.', '(201) 360-3072', 'https://www.ckokickboxing.com/nj-jersey-city/', 'First class free for new guests', ARRAY['beginner-friendly']::text[], false, 'https://www.ckokickboxing.com/find-your-location'),
  ('workouts', 'world-boxing-gym-jersey-city', 'World Boxing Gym', 'Boxing', 'Long-running Jersey City boxing gym offering group and private boxing training, open early morning to late evening on weekdays.', '29 Division St, Jersey City, NJ 07302', 'Hilltop / Journal Square, Jersey City', 40.7271::float8, -74.0522::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St, then walk ~15 min (or PATH to Journal Square and walk ~12 min).', '(201) 222-6565', 'https://www.worldboxinggym.com/', 'Group and private sessions (see site for pricing)', ARRAY['evening-hours']::text[], false, 'https://www.worldboxinggym.com/about'),
  ('workouts', 'asana-soul-practice-hoboken', 'Asana Soul Practice — Hoboken', 'Yoga', 'Judgment-free yoga studio with flow, stretch, strength and restorative classes, both heated and unheated, plus monthly community events like sound baths. New clients can start with 3 classes for $30.', '411 Jefferson St, Hoboken, NJ 07030', 'Midtown Hoboken', 40.7427::float8, -74.0369::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~15 min.', '(201) 792-5254', 'https://asanasoulpractice.com/', 'New clients: 3 classes for $30', ARRAY['beginner-friendly','yoga']::text[], false, 'https://asanasoulpractice.com/'),
  ('workouts', 'asana-soul-practice-jersey-city', 'Asana Soul Practice — Jersey City', 'Yoga', 'Downtown Jersey City sister studio to Asana Soul Hoboken, offering flow, stretch, strengthen and restore classes. New clients can start with 3 classes for $30.', '124 1st St, Jersey City, NJ 07302', 'Downtown Jersey City (Powerhouse Arts District)', 40.7215::float8, -74.0395::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~5 min.', '(201) 656-2612', 'https://asanasoulpractice.com/', 'New clients: 3 classes for $30', ARRAY['beginner-friendly','yoga']::text[], false, 'https://asanasoulpractice.com/'),
