  ('workouts', 'surya-yoga-academy-hoboken', 'Surya Yoga Academy — Hoboken', 'Hot yoga', 'Surya''s original Midtown Hoboken studio for hot yoga and other classes. First-time clients get their first month of hot and unheated yoga for $75.', '618 Washington St, Hoboken, NJ 07030', 'Midtown Hoboken', 40.7441::float8, -74.0292::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~15 min up Washington St.', '(201) 798-7498', 'https://www.suryayogaacademy.com/', 'New clients: first month $75', ARRAY['yoga']::text[], false, 'https://www.suryayogaacademy.com/pages/locations'),
  ('workouts', 'yogarenew-hoboken', 'YogaRenew — Hoboken', 'Yoga', 'Studio directly across from the Hoboken PATH with vinyasa, yin + sound, hatha, yoga sculpt, breathwork and pre/postnatal classes; all teachers are RYT-500 or higher. Free water and tea on site.', '12 Hudson Pl, Suite 201, Hoboken, NJ 07030', 'Downtown Hoboken', 40.7359::float8, -74.0285::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken; the studio is directly across from the station.', '(201) 540-9284', 'https://yogarenew.com/hoboken', 'Class packs and memberships (see site)', ARRAY['yoga']::text[], false, 'https://yogarenew.com/hoboken'),
  ('workouts', 'urban-souls-yoga-hoboken', 'Urban Souls Yoga', 'Yoga', 'Yoga and meditation studio in downtown Hoboken that also offers sound baths and breathwork. New students can get one month unlimited for $59.', '100 Hudson St, 4th Floor, Hoboken, NJ 07030', 'Downtown Hoboken', 40.7374::float8, -74.0301::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~4 min.', NULL::text, 'https://www.urbansoulsyoga.com/', 'New students: 1 month unlimited $59', ARRAY['yoga']::text[], false, 'https://www.urbansoulsyoga.com/'),
  ('workouts', 'powerflow-yoga-jersey-city', 'Powerflow Yoga — Jersey City', 'Yoga', 'Energetic power-flow studio a couple of blocks from Grove St PATH, with showers and changing rooms. New students get 30 days unlimited for $75, good at any of its studios.', '160 Morgan St, Jersey City, NJ 07302', 'Downtown Jersey City (Powerhouse Arts District)', 40.7201::float8, -74.0405::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~4 min (entrance at Marin Blvd & Bay St).', '(201) 433-2032', 'https://www.powerflow-yoga.com/studios/jersey-city', 'New students: 30 days unlimited $75; mat rental $3', ARRAY['yoga']::text[], false, 'https://www.powerflow-yoga.com/studios/jersey-city'),
  ('workouts', 'real-hot-yoga-hoboken', 'Real Hot Yoga — Hoboken', 'Hot yoga', 'Heated yoga studio in uptown Hoboken, part of a multi-city group. Offers a 30-day unlimited intro deal for new students (price varies by location).', '1414 Grand St, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7545::float8, -74.0316::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and walk ~12 min.', '(201) 222-1007', 'https://www.realhotyoga.net/', 'New-student 30-day unlimited intro (see site)', ARRAY['yoga']::text[], false, 'https://www.realhotyoga.net/'),
