  ('workouts', 'solidcore-jersey-city', '[solidcore] — Jersey City', 'Pilates', 'High-intensity, slow-and-controlled 50-minute workouts on [solidcore]''s custom reformer-style machine, in the VYV building near the waterfront.', '444 Warren St, Suite 2, Jersey City, NJ 07302', 'Harsimus Cove, Jersey City', 40.7216::float8, -74.0381::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St and walk ~8 min (Harsimus Cove light rail stop is 1 min away).', '(908) 808-5670', 'https://www.solidcore.co/studios/jersey-city', 'See site for intro offers and packs', ARRAY['pilates']::text[], false, 'https://www.solidcore.co/studios/jersey-city'),
  ('workouts', 'solidcore-hoboken', '[solidcore] — Hoboken', 'Pilates', '[solidcore]''s 50-minute reformer-style strength classes in the Maxwell Place complex in uptown Hoboken.', '1000 Maxwell Ln, Suite 105, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7492::float8, -74.0256::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~20 min north.', '(973) 319-8575', 'https://www.solidcore.co/studios/hoboken', 'See site for intro offers and packs', ARRAY['pilates']::text[], false, 'https://www.solidcore.co/studios/hoboken'),
  ('workouts', 'club-pilates-hoboken', 'Club Pilates — Hoboken', 'Pilates', 'Reformer-based Pilates studio on 15th St between Washington and Hudson. Offers a free 30-minute intro class with no credit card or commitment required.', '1400 Hudson St, Suite 3C, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7525::float8, -74.0252::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~25 min north (or Hudson-Bergen Light Rail to 9th St–Congress St and walk ~15 min).', '(201) 839-6648', 'https://www.clubpilates.com/hoboken', 'Free 30-min intro class; drop-ins and 4/8/unlimited memberships', ARRAY['beginner-friendly','pilates']::text[], false, 'https://www.clubpilates.com/hoboken'),
  ('workouts', 'club-pilates-jersey-city', 'Club Pilates — Jersey City', 'Pilates', 'Reformer-based Pilates studio in downtown Jersey City. Offers a free 30-minute intro class with no credit card or commitment required.', '171 Morgan St, Jersey City, NJ 07302', 'Downtown Jersey City (Powerhouse Arts District)', 40.7199::float8, -74.0404::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~5 min.', '(201) 201-8020', 'https://www.clubpilates.com/jerseycity', 'Free 30-min intro class; memberships available', ARRAY['beginner-friendly','pilates']::text[], false, 'https://www.clubpilates.com/jerseycity'),
  ('workouts', 'pilates-haus-jersey-city', 'Pilates Haus', 'Pilates', 'Classical Pilates studio offering group classes and private sessions, home to a long-running classical teacher certification program. Open until 9 pm on weekdays.', '140 Bay St, Retail #4, Jersey City, NJ 07302', 'Downtown Jersey City (Powerhouse Arts District)', 40.7209::float8, -74.0391::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~5 min.', '(201) 963-0436', 'https://www.pilateshaus.com/', 'Group classes and private sessions (see site)', ARRAY['evening-hours','pilates']::text[], false, 'https://www.pilateshaus.com/'),
  ('workouts', 'project-pilates-jersey-city', 'Project Pilates', 'Pilates', 'Small-group (6-person) equipment classes on reformers, Wunda chairs and wall towers, with levels from Basics for Beginners up to Advanced. New clients start with an Intro to Equipment class.', '190 Christopher Columbus Dr, #5A, Jersey City, NJ 07302', 'Downtown Jersey City (Grove St)', 40.721::float8, -74.0473::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~5 min.', '(201) 432-5849', 'https://www.projectpilates.com/', 'Class packs (1/5/10/20) and monthly memberships', ARRAY['beginner-friendly','pilates']::text[], false, 'https://www.projectpilates.com/'),
  ('workouts', 'wundabar-pilates-jersey-city', 'WundaBar Pilates — Jersey City', 'Pilates', 'WundaBar''s Pilates classes on its signature WundaFormer machine, at a downtown Jersey City studio near Newport and Grove St.', '65 Bay St, Jersey City, NJ 07302', 'Downtown Jersey City (Harsimus)', 40.7203::float8, -74.0376::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St (or F/M to 14 St and PATH to Newport); walk ~7 min.', '(845) 999-6727', 'https://www.wundabar.com/jersey-city', 'See site for pricing', ARRAY['pilates']::text[], false, 'https://www.wundabar.com/jersey-city'),
  ('workouts', 'power-house-pilates-jersey-city', 'Power-House Pilates', 'Pilates', 'Boutique downtown Jersey City studio focused on private sessions and intentionally small group classes for full-body Pilates.', '189 Brunswick St, Jersey City, NJ 07302', 'Hamilton Park, Jersey City', 40.7261::float8, -74.0505::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~12 min.', '(201) 963-9100', 'https://www.power-housepilates.com/', 'Private and group sessions (see site)', ARRAY['pilates']::text[], false, 'https://www.power-housepilates.com/'),
  ('workouts', 'new-heights-pilates-jersey-city', 'New Heights Pilates', 'Pilates', 'Reformer studio in the Heights "rooted in the principles of classical Pilates and taught through a modern lens," with certified teachers and small classes.', '10 South St, Jersey City, NJ 07307', 'The Heights, Jersey City', 40.7474::float8, -74.0417::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, Hudson-Bergen Light Rail to 9th St–Congress St, take the elevator up to the Heights and walk ~6 min (entrance on Palisade Ave).', '(551) 225-0490', 'https://www.newheightspilates.com/', 'Memberships and class packs (see site)', ARRAY['pilates']::text[], false, 'https://www.newheightspilates.com/'),
  ('workouts', 'ken-pilates-hoboken', 'Ken Pilates', 'Pilates', 'Hoboken studio built around springboard classes (SpringSculpt, heated HotSprings), plus Hot Mat Sculpt, a yoga-Pilates fusion and stretch classes.', '706 Washington St, Hoboken, NJ 07030', 'Midtown Hoboken', 40.7451::float8, -74.0289::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~17 min up Washington St.', NULL::text, 'https://www.kenpilates.com/', 'Memberships and packs (see site)', ARRAY['pilates','yoga']::text[], false, 'https://www.kenpilates.com/'),
  ('clubs', 'little-city-books-hoboken', 'Little City Books', 'Books & events', 'Hoboken''s independent bookstore, with frequent author talks, the monthly Little City Book Club and the Hoboken Writers group. Many events require free registration or tickets.', '100 Bloomfield St, Hoboken, NJ 07030', 'Downtown Hoboken', 40.7377::float8, -74.0318::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~8 min.', NULL::text, 'https://www.littlecitybooks.com/', 'Events often require free registration or tickets (see site)', ARRAY['evening-hours']::text[], false, 'https://www.littlecitybooks.com/events'),
  ('clubs', 'word-bookstore-jersey-city', 'WORD Jersey City', 'Books & events', 'Independent bookstore by Hamilton Park that runs book clubs and a regular calendar of readings, book launches and panels.', '29 McWilliams Pl, Jersey City, NJ 07302', 'Hamilton Park, Jersey City', 40.7282::float8, -74.0439::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St and walk ~12 min (or F/M to 14 St, PATH to Newport and walk ~12 min).', '(201) 763-6611', 'https://www.wordbookstores.com/', 'Free to browse; see site for event details', '{}'::text[], false, 'https://www.wordbookstores.com/'),
  ('clubs', 'dungeon-books-jersey-city', 'Dungeon Books', 'Book club', 'Jersey City bookstore specializing in sci-fi, fantasy and tabletop RPGs, with several monthly book clubs (sci-fi & fantasy, horror, fantasy romance). Book clubs run about an hour and are typically free.', '115 Brunswick St, Jersey City, NJ 07302', 'Hamilton Park, Jersey City', 40.7229::float8, -74.051::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~10 min.', NULL::text, 'https://www.dungeonbooks.com/', 'Book clubs free', ARRAY['free','evening-hours']::text[], true, 'https://app.hi.events/event/9308/july-sci-fi-fantasy-book-club-july-30'),
  ('clubs', 'symposia-community-bookstore-hoboken', 'Symposia Community Bookstore', 'Books & events', 'Nonprofit, donation-based, volunteer-run community bookstore in Hoboken since 2003. Hosts a Silent Book Club, open mics, figure drawing and improv workshops, and takes volunteers.', '510 Washington St, Hoboken, NJ 07030', 'Midtown Hoboken', 40.7426::float8, -74.0296::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~12 min up Washington St.', NULL::text, 'https://symposiabookstore.com/', 'Many events free or donation-based', ARRAY['low-cost']::text[], false, 'https://symposiabookstore.com/contact-us/'),
  ('clubs', 'mile-square-theatre-hoboken', 'Mile Square Theatre', 'Arts & classes', 'Hoboken''s professional theatre, which also runs classes for artists of all ages and skill levels, described as a welcoming, inclusive space to learn.', '1400 Clinton St, Hoboken, NJ 07030', 'Uptown Hoboken', 40.7542::float8, -74.0306::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and walk ~12 min.', '(201) 683-7014', 'https://www.milesquaretheatre.org/classes/', 'See class schedule for prices', ARRAY['beginner-friendly']::text[], false, 'https://www.milesquaretheatre.org/classes/'),
  ('clubs', 'art-house-productions-jersey-city', 'Art House Productions', 'Arts & classes', 'Nonprofit arts center at The Hendrix presenting theater, gallery exhibitions, JC Fridays and the annual Jersey City Comedy Festival, plus art classes.', '345 Marin Blvd, Jersey City, NJ 07302', 'Downtown Jersey City (Grove St)', 40.7207::float8, -74.0418::float8, 'J/Z from Bowery to Chambers St, walk to World Trade Center PATH, PATH to Grove St; walk ~3 min (between Bay St and Morgan St).', '(201) 579-0532', 'https://www.arthouseproductions.org/', 'Many gallery shows and events free; some ticketed', '{}'::text[], false, 'https://www.arthouseproductions.org/pages/directions'),
  ('clubs', 'jersey-creative-lab-improv-hoboken-jersey-city', 'Jersey Creative Lab (Jersey Improv Lab)', 'Comedy & improv', 'Comedy-focused performing arts group running multi-week Intro to Improv, Level 2 improv and stand-up writing workshops for adults. Classes meet in Downtown Hoboken (at Symposia Bookstore) and in Downtown/Hamilton Park Jersey City.', NULL::text, 'Downtown Hoboken and Downtown Jersey City', NULL::float8, NULL::float8, NULL::text, NULL::text, 'https://jerseycreativelab.com/', 'Paid multi-week workshops (register via Eventbrite)', ARRAY['beginner-friendly','evening-hours']::text[], false, 'https://jerseycreativelab.com/'),
  ('clubs', 'north-river-sing-community-chorus-jersey-city', 'North River Sing', 'Music & choir', 'Jersey City community chorus devoted to American musical theatre, with seasonal concerts. Audition info, rehearsal details and dues/financial aid are listed on its site.', NULL::text, 'Downtown Jersey City', NULL::float8, NULL::float8, NULL::text, '(201) 589-1552', 'https://www.northriversing.org/', 'Membership dues (financial aid available — see site)', '{}'::text[], false, 'https://www.northriversing.org/'),
  ('clubs', 'blue-skies-pottery-hoboken', 'Blue Skies Pottery — Hoboken', 'Crafting', 'Community pottery studio in the Monroe Center that welcomes first-timers, with one-time wheel classes and multi-week courses like Wheel 101.', '720 Monroe St, Suite C414, Hoboken, NJ 07030', 'Northwest Hoboken', 40.7475::float8, -74.0378::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then Hudson-Bergen Light Rail to 9th St–Congress St and walk ~5 min.', '(201) 559-3833', 'https://www.blueskiespottery.com/', 'One-time wheel classes from $85; adult multi-week courses $70–$85/week', ARRAY['beginner-friendly']::text[], false, 'https://www.blueskiespottery.com/'),
  ('clubs', 'hoboken-shelter-volunteer', 'The Hoboken Shelter', 'Volunteering', 'Hoboken''s homeless shelter, which welcomes individual volunteers to serve meals, help in the kitchen or assist with special events, plus group and off-site service projects.', '300 Bloomfield St, Hoboken, NJ 07030', 'Downtown Hoboken', 40.7404::float8, -74.031::float8, 'F/M from Delancey St–Essex St to 14 St (6 Av), PATH to Hoboken, then walk ~10 min.', '(201) 656-5069', 'https://www.hobokenshelter.org/volunteer', 'Free', ARRAY['free']::text[], true, 'https://www.hobokenshelter.org/volunteer')
) AS v(cat, slug, name, kind, description, address, neighborhood, lat, lng, transit, phone, website, cost, tags, is_free, source_url)
JOIN categories c ON c.slug = v.cat
ON CONFLICT (slug) DO NOTHING;

-- ───────────── Beauty: hair, nails, brows, waxing, makeup, facials (Oct 2026) ─────────────
INSERT INTO listings
  (category_id, slug, name, kind, description, address, neighborhood, lat, lng, transit, phone, website, cost, tags, is_free, source_url)
SELECT c.id, v.slug, v.name, v.kind, v.description, v.address, v.neighborhood, v.lat, v.lng,
       v.transit, v.phone, v.website, v.cost, v.tags, v.is_free, v.source_url
FROM (VALUES
  ('beauty', 'aveda-institute-new-york-dumbo', 'Aveda Arts & Sciences Institute New York', 'Beauty school (discount)', 'Aveda''s NYC cosmetology school, now in DUMBO, offers haircuts, color, blowouts and skin care by students working under close educator supervision. Services use Aveda products and cost a fraction of full-salon prices.', '20 Jay St, Brooklyn, NY 11201', 'DUMBO', 40.7041::float8, -73.9867::float8, 'F from Delancey St–Essex St to York St, 5-min walk', '212-807-1492', 'https://aveda.edu/locations/location/new-york-ny/', 'Discounted student-stylist services', ARRAY['low-cost','evening-hours']::text[], false, 'https://aveda.edu/locations/location/new-york-ny/'),
  ('beauty', 'empire-beauty-school-manhattan', 'Empire Beauty School – New York City (Manhattan)', 'Beauty school (discount)', 'This Midtown cosmetology school runs a student salon where senior students handle hair, skin and nail services under licensed educators, for less than typical salon prices. Book online or by phone.', '22 W 34th St, New York, NY 10001', 'Midtown / Herald Square', 40.749::float8, -73.9863::float8, 'B/D from Grand St to 34 St–Herald Sq, 3-min walk', '332-322-6138', 'https://empire.edu/cosmetology-schools/new-york/new-york-city-manhattan', 'Discounted student-stylist services; check campus for current rates', ARRAY['low-cost','evening-hours']::text[], false, 'https://empire.edu/cosmetology-schools/new-york/new-york-city-manhattan'),
  ('beauty', 'arrojo-academy-student-salon', 'ARROJO Academy Student Salon', 'Beauty school (discount)', 'ARROJO''s licensed beauty school runs a student salon where cosmetology, barbering and esthetics students do cuts, color, blowouts and facials under instructor supervision. Consultations are free, and you may be asked to act as a class demonstration model.', '180 Varick St, New York, NY 10014', 'Hudson Square', 40.7275::float8, -74.0051::float8, 'F/M from Delancey St–Essex St to W 4 St–Wash Sq, 10-min walk', '212-242-7786', 'https://arrojoacademy.com/student-salon', 'Student services from about $15 (blow dry) to $108 (freehand color); barber cuts $20', ARRAY['low-cost','evening-hours']::text[], false, 'https://arrojoacademy.com/student-salon'),
  ('beauty', 'ouidad-flagship-salon-flatiron', 'Ouidad Flagship Salon', 'Curly & textured hair', 'Ouidad''s own NYC salon focuses on curly, coily and wavy hair. Stylists identify your curl type, cut for your pattern and show you how to care for your curls between visits.', '9 E 19th St, New York, NY 10003', 'Flatiron', 40.7389::float8, -73.9905::float8, 'F/M from Delancey St–Essex St to 23 St, 5-min walk', '212-888-3288', 'https://www.ouidad.com/pages/salons', 'Check site for current pricing', '{}'::text[], false, 'https://www.ouidad.com/pages/salons'),
  ('beauty', 'hair-rules-studio-hells-kitchen', 'Hair Rules Studio', 'Curly & textured hair', 'Hair Rules'' flagship studio offers texture-specific cuts and care for all hair types, with a focus on teaching you to manage your natural texture at home. It''s by appointment only, on the third floor of a walk-up with no elevator.', '828 9th Ave, 3rd Floor, New York, NY 10019', 'Hell''s Kitchen', 40.7661::float8, -73.9867::float8, 'B/D from Grand St to 7 Av, 7-min walk', NULL::text, 'https://hairrules.com/studio', 'Check site for current pricing', '{}'::text[], false, 'https://hairrules.com/studio'),
  ('beauty', 'headchop-williamsburg', 'Headchop', 'Curly & textured hair', 'A Williamsburg salon built around dry cutting, so stylists cut your hair in its natural state and it doesn''t shrink shorter than expected. They also do root touch-ups and event styling.', '98 S 4th St, Brooklyn, NY 11249', 'Williamsburg', 40.7122::float8, -73.9641::float8, 'J/Z from Bowery to Marcy Av, 8-min walk', '347-844-9635', 'https://www.headchop.com/', 'Check site for current pricing', '{}'::text[], false, 'https://www.headchop.com/'),
  ('beauty', 'spiral-xyz-tribeca', 'Spiral (x,y,z)', 'Curly & textured hair', 'A Tribeca curly-hair salon from curly-girl pioneer Lorraine Massey. It offers Curl by Curl cutting and Color by Curl services, plus classes and workshops on caring for curls.', '139 West Broadway, New York, NY 10013', 'Tribeca', 40.7168::float8, -74.0081::float8, 'J/Z from Bowery to Chambers St, 7-min walk', '917-261-6794', 'https://www.spiralxyz.com/', 'Check site for current pricing', '{}'::text[], false, 'https://www.spiralxyz.com/'),
  ('beauty', 'salon-bohemia-park-slope', 'Salon Bohemia', 'Curly & textured hair', 'A long-running Park Slope Paul Mitchell Focus Salon that works with every texture, whether coily, curly, wavy or straight. It offers cuts, color, perms and event styling.', '437 7th Ave, Brooklyn, NY 11215', 'Park Slope', 40.6633::float8, -73.9843::float8, 'F from Delancey St–Essex St to 15 St–Prospect Park, 7-min walk', '718-788-8750', 'https://www.salonbohemia.com/', 'Check site for current pricing', '{}'::text[], false, 'https://www.salonbohemia.com/'),
  ('beauty', 'bubbles-and-mane-astoria', 'Bubbles & Mane (formerly Astoria Beauty Bar)', 'Curly & textured hair', 'An Astoria salon that specializes in curly hair, with curl consultations, scalp-steaming head spa treatments and custom deep conditioning. It also offers nails, facials and bridal styling.', '23-67 31st St, Astoria, NY 11105', 'Astoria', 40.7741::float8, -73.9128::float8, 'B/D from Grand St to 34 St–Herald Sq, transfer to N/W to Astoria–Ditmars Blvd, 3-min walk', '917-838-1142', 'https://www.astoriabeautybar.com/', 'Check site for current pricing', '{}'::text[], false, 'https://www.astoriabeautybar.com/'),
  ('beauty', 'tousled-hair-salon-jersey-city', 'Tousled Hair Salon', 'Curly & textured hair', 'A downtown Jersey City Aveda salon that specializes in curl and texture. The curly cut includes a dry shaping cut, a scalp detox and a steam deep-conditioning treatment.', '500-A Jersey Ave, Jersey City, NJ 07302', 'Downtown Jersey City', 40.7197::float8, -74.047::float8, 'F/M to 14 St, PATH to Grove St (or J/Z to Chambers St, WTC PATH to Grove St), 6-min walk', '201-309-1200', 'http://www.mytousledhair.com/', 'Curly cut packages about $195–$225', '{}'::text[], false, 'http://www.mytousledhair.com/'),
  ('beauty', 'h2-salon-bed-stuy', 'H2 Salon', 'Braids & natural hair', 'A Bed-Stuy salon for natural and textured hair. Services range from silk presses and natural styling to protective styles and safe color.', '473 Tompkins Ave, Brooklyn, NY 11216', 'Bed-Stuy', 40.6813::float8, -73.9433::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, transfer to C to Kingston–Throop Avs, 4-min walk', '718-230-4225', 'https://www.h2salonbk.com/', 'Check site for current pricing', ARRAY['evening-hours']::text[], false, 'https://www.h2salonbk.com/'),
  ('beauty', 'hair-and-co-bklyn-prospect-heights', 'Hair & Co BKLYN – Prospect Heights', 'Braids & natural hair', 'A Prospect Heights salon for textured hair that offers silk presses, loc retwists and maintenance, braiding and Ouidad-certified curly cuts.', '477 Bergen St, Brooklyn, NY 11217', 'Prospect Heights', 40.6809::float8, -73.9747::float8, 'B/D from Grand St to Atlantic Av–Barclays Ctr, 6-min walk', '347-294-4600', 'https://hairandcobklyn.com/', 'Cut & style about $85–$145; silk press about $130–$190', '{}'::text[], false, 'https://hairandcobklyn.com/services/'),
  ('beauty', 'latifa-natural-hair-salon-downtown-brooklyn', 'Latifa Natural Hair Salon', 'Braids & natural hair', 'An African hair-braiding salon in Downtown Brooklyn offering box braids, faux locs, kinky twists, locs and weaves for any natural hair type.', '228 Livingston St, 2nd Floor, Brooklyn, NY 11201', 'Downtown Brooklyn', 40.6893::float8, -73.9852::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, 6-min walk', '347-763-1628', 'https://www.hairbylatifa.com/', 'Check site for current pricing', '{}'::text[], false, 'https://www.hairbylatifa.com/'),
  ('beauty', 'kadija-hair-braiding-bed-stuy', 'Kadija Hair Braiding', 'Braids & natural hair', 'A Bed-Stuy braiding shop offering knotless, box and goddess braids, cornrows, passion twists and more, with online booking. A $20 deposit is due at booking and the balance is paid in cash.', '191 Malcolm X Blvd, Brooklyn, NY 11221', 'Bed-Stuy', 40.6866::float8, -73.9297::float8, 'J from Bowery to Gates Av, 10-min walk', '347-322-7710', 'https://kadijahairbraidingbedstuy.setmore.com/', 'Listed styles about $40–$400 depending on size and length', '{}'::text[], false, 'https://kadijahairbraidingbedstuy.setmore.com/'),
  ('beauty', 'camera-ready-kutz-crown-heights', 'Camera Ready Kutz', 'Hair salon', 'A Black-owned barbershop in Crown Heights that welcomes everyone and centers LGBTQIA+ clients. It offers gender-affirming haircuts, loc services and hair units.', '71 Utica Ave, Brooklyn, NY 11213', 'Crown Heights', 40.6765::float8, -73.9302::float8, 'F from Delancey St–Essex St to Jay St–MetroTech, transfer to A to Utica Av, 4-min walk', '347-349-5889', 'http://www.camerareadykutz.com/', 'Check site for current pricing', ARRAY['lgbtq-affirming']::text[], false, 'http://www.camerareadykutz.com/'),
  ('beauty', 'hairrari-east-village', 'Hairrari – East Village', 'Hair salon', 'A gender-neutral barbershop and salon that is woman-, immigrant- and queer-owned, welcoming all hair types and styles. This is the original location, a short walk from the LES.', '34 E 1st St, New York, NY 10003', 'East Village', 40.7242::float8, -73.9904::float8, 'F from Delancey St–Essex St to 2 Av, 3-min walk (or 10-min walk)', '917-388-2114', 'https://www.hairrari.com/', 'Check site for current pricing', ARRAY['lgbtq-affirming','evening-hours']::text[], false, 'https://www.hairrari.com/'),
  ('beauty', 'hairrari-williamsburg', 'Hairrari – Williamsburg', 'Hair salon', 'The Williamsburg location of Hairrari, a gender-neutral, queer-owned barbershop and salon that welcomes every hair type.', '41 Havemeyer St, Brooklyn, NY 11211', 'Williamsburg', 40.7155::float8, -73.9537::float8, 'J/Z from Bowery to Marcy Av, 10-min walk', '347-799-1849', 'https://www.hairrari.com/', 'Check site for current pricing', ARRAY['lgbtq-affirming','evening-hours']::text[], false, 'https://www.hairrari.com/'),
  ('beauty', 'hairrari-bushwick', 'Hairrari – Bushwick', 'Hair salon', 'The Bushwick location of Hairrari, a gender-neutral, queer-owned barbershop and salon for all hair types, open daily from noon.', '206 Bushwick Ave, Brooklyn, NY 11206', 'Bushwick', 40.7087::float8, -73.9402::float8, 'F/M from Delancey St–Essex St to 14 St, transfer to L at 6 Av to Montrose Av, 2-min walk', '347-689-3363', 'https://www.hairrari.com/', 'Check site for current pricing', ARRAY['lgbtq-affirming','evening-hours']::text[], false, 'https://www.hairrari.com/'),
  ('beauty', 'mutiny-queer-barbers-gowanus', 'Mutiny', 'Hair salon', 'A Brooklyn barbershop run by queer barbers for queer clients, offering short and long cuts, buzzes and bang trims. Free touch-ups are available within 7 days, and limited pay-what-you-wish slots are offered.', '117 9th St, #227, Brooklyn, NY 11215', 'Gowanus', 40.673::float8, -73.994::float8, 'F from Delancey St–Essex St to Smith–9 Sts, 5-min walk', NULL::text, 'https://mutiny.gay/', 'Cuts $50–$70; buzz $30; limited pay-what-you-wish availability', ARRAY['lgbtq-affirming','sliding-scale']::text[], false, 'https://mutiny.gay/services'),
  ('beauty', 'toto-hair-grand-street', 'Toto Hair', 'Hair salon', 'A Wella Concept Salon in Chinatown and Little Italy offering haircuts, balayage, keratin treatments, Japanese straightening and digital perms. Staff can help in English and Chinese.', '201 Grand St, 2nd Floor, New York, NY 10013', 'Chinatown / Little Italy', 40.719::float8, -73.9968::float8, '8-min walk west along Grand St', '212-431-1630', 'https://totohair.salon/', 'Check site for current pricing', ARRAY['chinese']::text[], false, 'https://totohair.salon/'),
