ON CONFLICT (slug) DO NOTHING;

-- Yoga & Pilates live under Workouts; tag them so the "Yoga classes" / "Pilates classes" filters include the studios.
UPDATE listings SET tags = array_append(tags, 'yoga')
WHERE kind IN ('Yoga', 'Hot yoga', 'Donation-based yoga', 'Free outdoor yoga') AND NOT 'yoga' = ANY(tags);
UPDATE listings SET tags = array_append(tags, 'pilates')
WHERE kind = 'Pilates' AND NOT 'pilates' = ANY(tags);
